// Robust Panchayat Normalization Helper (Heals spelling variants e.g., 'Sandrooon' with 3 o's to 'Sandroon')
function normalizePanchayatName(str) {
  if (!str) return '';
  const s = String(str).trim();
  const clean = s.toLowerCase().replace(/[^a-z0-9]/g, '');
  if (clean.startsWith('sandro')) return 'Sandroon';
  if (clean.startsWith('lowangn')) return 'Lowang North';
  if (clean.startsWith('lowangs')) return 'Lowang South';
  if (clean.startsWith('sitt') || clean === 'siti') return 'Sitti';
  if (clean.startsWith('fateh')) return 'Fatehpur';
  if (clean.startsWith('barmot')) return 'Barmota';
  if (clean.startsWith('bhand')) return 'Bhandar';
  if (clean.startsWith('chand')) return 'Chandal';
  if (clean.startsWith('doul') || clean.startsWith('dolk')) return 'Doulka';
  if (clean.startsWith('gatt')) return 'Gatti';
  if (clean.startsWith('kanth')) return 'Kanthal';
  if (clean.startsWith('kard')) return 'Kardoh';
  if (clean.startsWith('roul') || clean.startsWith('rolk')) return 'Roulka';
  if (clean.startsWith('sandh') || clean === 'sandi') return 'Sandhi';
  if (clean.startsWith('siar')) return 'Siara';
  if (clean === 'asso') return 'Asso';
  if (clean === 'bani') return 'Bani';
  const match = PANCHAYATS.find(p => p.toLowerCase() === s.toLowerCase());
  return match || s;
}
window.normalizePanchayatName = normalizePanchayatName;

// Financial 3-Decimal Precision Formatter (Preserves exact Lakhs precision e.g. 1.725, 2.475, 161.085)
function fmtNum3(v) {
  if (v === null || v === undefined || v === '') return '0.000';
  const n = Number(v);
  if (isNaN(n)) return '0.000';
  return n.toFixed(3);
}
window.fmtNum3 = fmtNum3;

