function formatSheet3Cell(val, isTotal = false) {
  if (val === undefined || val === null || val === '') {
    return isTotal ? '0' : '<span class="text-slate-300">-</span>';
  }
  return val;
}


function groupSheet3Rows(rows) {
  const groups = [];
  let currentGroup = null;

  (rows || []).forEach(r => {
    if (r.isGrandTotal) {
      groups.push({ type: 'grand', row: r });
    } else if (r.isTotal) {
      if (currentGroup) {
        currentGroup.totalRow = r;
        groups.push(currentGroup);
        currentGroup = null;
      }
    } else {
      if (!currentGroup || currentGroup.constituency !== r.constituency) {
        if (currentGroup) groups.push(currentGroup);
        currentGroup = {
          type: 'constituency',
          sNo: r.sNo || (groups.length + 1),
          constituency: r.constituency,
          rows: []
        };
      }
      currentGroup.rows.push(r);
    }
  });
  if (currentGroup) groups.push(currentGroup);
  return groups;
}

