// ============================================================================
// SHEET #1: DAILY BANI PROGRESS (112 WORKS) LIVE GOOGLE SHEET ENGINE
// Authority Google Sheet: https://docs.google.com/spreadsheets/d/10vQXS5D36tGuvaBNEpe4xYBRs6RKUqv6BHq_eboosNQ/edit?gid=1884788730#gid=1884788730
// Contains 2 Verbatim Sheets:
//   1. Physical Progress (Physical-2026-27 - 34 Columns verbatim)
//   2. Financial Expenditure (Financial-2026-27 - 15 Columns verbatim)
// ============================================================================

const SHEET1_BANI_GOOGLE_SHEET_ID = '10vQXS5D36tGuvaBNEpe4xYBRs6RKUqv6BHq_eboosNQ';
const SHEET1_BANI_GOOGLE_SHEET_CSV_URL = 'https://docs.google.com/spreadsheets/d/' + SHEET1_BANI_GOOGLE_SHEET_ID + '/export?format=csv&gid=1884788730';
const SHEET1_BANI_GOOGLE_SHEET_PAGE_URL = 'https://docs.google.com/spreadsheets/d/10vQXS5D36tGuvaBNEpe4xYBRs6RKUqv6BHq_eboosNQ/edit?gid=1884788730#gid=1884788730';

let sheet1BaniState = {
  filterCapexOnly: false,
  isRefreshing: false
};

function formatSheetDate(val) {
  if (val === null || val === undefined || val === '') return '';
  if (typeof val === 'number') {
    const date = new Date(Math.round((val - 25569) * 86400 * 1000));
    const day = String(date.getUTCDate()).padStart(2, '0');
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const month = months[date.getUTCMonth()];
    const year = date.getUTCFullYear();
    return `${day}-${month}-${year}`;
  }
  return String(val).trim();
}

function cleanSheetVal(v) {
  if (v === null || v === undefined) return '';
  if (typeof v === 'number') {
    if (Number.isInteger(v)) return String(v);
    const fixed = v.toFixed(3);
    return parseFloat(fixed).toString();
  }
  return String(v).trim();
}

function getSheet1DailyBaniData() {
  try {
    if (typeof window !== 'undefined' && window.sheet1DailyBaniLiveCache) {
      return window.sheet1DailyBaniLiveCache;
    }
    if (typeof localStorage !== 'undefined') {
      const cached = localStorage.getItem('bdo_sheet1_bani_live_cache');
      if (cached) {
        const parsed = JSON.parse(cached);
        if (typeof window !== 'undefined') window.sheet1DailyBaniLiveCache = parsed;
        return parsed;
      }
    }
  } catch (e) {}
  if (typeof window !== 'undefined' && window.sheet1DailyBaniBaselineData) {
    return window.sheet1DailyBaniBaselineData;
  }
  if (typeof global !== 'undefined' && global.sheet1DailyBaniBaselineData) {
    return global.sheet1DailyBaniBaselineData;
  }
  return null;
}

function parseSheet1RawData(physRows, finRows) {
  if (!physRows || physRows.length < 20) return null;

  function parsePhysSection(rows, startIdx, endIdx, totalIdx) {
    const items = [];
    for (let i = startIdx; i <= endIdx && i < rows.length; i++) {
      const r = rows[i] || [];
      if (!r[2]) continue;
      items.push({
        block: 'Bani',
        sNo: cleanSheetVal(r[1]),
        component: cleanSheetVal(r[2]),
        totalWorks: cleanSheetVal(r[3]),
        nonConstt: (r.slice(4, 14)).map(cleanSheetVal),
        constt: (r.slice(14, 24)).map(cleanSheetVal),
        total: (r.slice(24, 34)).map(cleanSheetVal)
      });
    }
    const totR = rows[totalIdx] || [];
    const subTotal = {
      sNo: '',
      component: cleanSheetVal(totR[2]) || 'Sub-Total',
      totalWorks: cleanSheetVal(totR[3]),
      nonConstt: (totR.slice(4, 14)).map(cleanSheetVal),
      constt: (totR.slice(14, 24)).map(cleanSheetVal),
      total: (totR.slice(24, 34)).map(cleanSheetVal),
      isTotal: true
    };
    return { items, subTotal };
  }

  function parseFinSection(rows, startIdx, endIdx, totalIdx) {
    const items = [];
    if (!rows || rows.length <= totalIdx) return { items: [], subTotal: null };
    for (let i = startIdx; i <= endIdx && i < rows.length; i++) {
      const r = rows[i] || [];
      if (!r[2]) continue;
      items.push({
        block: 'Bani',
        sNo: cleanSheetVal(r[1]),
        component: cleanSheetVal(r[2]),
        billsRecCount: cleanSheetVal(r[3]),
        billsRecAmt: cleanSheetVal(r[4]),
        billsClrCount: cleanSheetVal(r[5]),
        billsClrAmt: cleanSheetVal(r[6]),
        actualClrCount: cleanSheetVal(r[7]),
        actualClrAmt: cleanSheetVal(r[8]),
        tryPendingCount: cleanSheetVal(r[9]),
        tryPendingAmt: cleanSheetVal(r[10]),
        approvedOutlay: cleanSheetVal(r[11]),
        fundsReceived: cleanSheetVal(r[12]),
        allotmentCost: cleanSheetVal(r[13]),
        expPercentage: cleanSheetVal(r[14])
      });
    }
    const totR = rows[totalIdx] || [];
    const subTotal = {
      sNo: '',
      component: cleanSheetVal(totR[2]) || 'Sub-Total',
      billsRecCount: cleanSheetVal(totR[3]),
      billsRecAmt: cleanSheetVal(totR[4]),
      billsClrCount: cleanSheetVal(totR[5]),
      billsClrAmt: cleanSheetVal(totR[6]),
      actualClrCount: cleanSheetVal(totR[7]),
      actualClrAmt: cleanSheetVal(totR[8]),
      tryPendingCount: cleanSheetVal(totR[9]),
      tryPendingAmt: cleanSheetVal(totR[10]),
      approvedOutlay: cleanSheetVal(totR[11]),
      fundsReceived: cleanSheetVal(totR[12]),
      allotmentCost: cleanSheetVal(totR[13]),
      expPercentage: cleanSheetVal(totR[14]),
      isTotal: true
    };
    return { items, subTotal };
  }

  return {
    sheetId: SHEET1_BANI_GOOGLE_SHEET_ID,
    lastSync: new Date().toISOString(),
    physical: {
      title: 'Physical Progress under Different Schemes for the financial year 2026-27',
      gid: '1884788730',
      sectionA: parsePhysSection(physRows, 5, 19, 20),
      sectionB: parsePhysSection(physRows, 22, 36, 37),
      sectionC: parsePhysSection(physRows, 39, 53, 54)
    },
    financial: finRows ? {
      title: 'Status of Expenditure under DCB / UT, 2026-27',
      subtitle: '(₹ in Lakhs)',
      gid: '113066318',
      sectionA: parseFinSection(finRows, 5, 19, 20),
      sectionB: parseFinSection(finRows, 22, 36, 37),
      sectionC: parseFinSection(finRows, 39, 53, 54)
    } : (window.sheet1DailyBaniBaselineData ? window.sheet1DailyBaniBaselineData.financial : null)
  };
}

async function fetchSheet1LiveBaniData(userTriggered = false) {
  if (sheet1BaniState.isRefreshing && !userTriggered) return;
  sheet1BaniState.isRefreshing = true;

  const refreshBtn = typeof document !== 'undefined' ? document.getElementById('sheet1-refresh-btn') : null;
  if (refreshBtn) {
    refreshBtn.innerHTML = '<i class="fa-solid fa-arrows-rotate animate-spin mr-1.5 text-blue-200"></i> <span>Syncing...</span>';
    refreshBtn.disabled = true;
  }

  let parsed = null;

  // 1. Try local server API endpoint (using getBackendBaseUrl to support Electron file://)
  try {
    const apiBase = typeof getBackendBaseUrl === 'function' ? getBackendBaseUrl() : ((window.location.protocol === 'http:' || window.location.protocol === 'https:') ? '' : 'http://localhost:3000');
    const apiRes = await fetch(apiBase + '/api/sheet1-bani-sheet', { cache: 'no-store' });
    if (apiRes.ok) {
      const json = await apiRes.json();
      if (json.success && json.physRows) {
        parsed = parseSheet1RawData(json.physRows, json.finRows);
      }
    }
  } catch (apiErr) {
    console.warn('[Sheet 1 Live API Notice]', apiErr.message);
  }

  // 2. Direct browser fetch from Google Sheets XLSX export if proxy failed
  if (!parsed && typeof XLSX !== 'undefined') {
    try {
      const gUrl = 'https://docs.google.com/spreadsheets/d/' + SHEET1_BANI_GOOGLE_SHEET_ID + '/export?format=xlsx';
      const directRes = await fetch(gUrl, { cache: 'no-store' });
      if (directRes.ok) {
        const ab = await directRes.arrayBuffer();
        const wb = XLSX.read(ab, { type: 'array' });
        const physRows = XLSX.utils.sheet_to_json(wb.Sheets['Physical-2026-27'] || {}, { header: 1 });
        const finRows = XLSX.utils.sheet_to_json(wb.Sheets['Financial-2026-27'] || {}, { header: 1 });
        if (physRows && physRows.length > 0) {
          parsed = parseSheet1RawData(physRows, finRows);
        }
      }
    } catch (directErr) {
      console.warn('[Sheet 1 Direct Fetch Notice]', directErr.message);
    }
  }

  sheet1BaniState.isRefreshing = false;
  if (refreshBtn) {
    refreshBtn.innerHTML = '<i class="fa-solid fa-arrows-rotate mr-1.5" style="color: #a7f3d0 !important;"></i> <span>Refresh Live Sheet</span>';
    refreshBtn.disabled = false;
  }

  if (parsed) {
    if (typeof window !== 'undefined') window.sheet1DailyBaniLiveCache = parsed;
    try {
      if (typeof localStorage !== 'undefined') localStorage.setItem('bdo_sheet1_bani_live_cache', JSON.stringify(parsed));
    } catch (e) {}

    if (userTriggered && typeof showToast === 'function') {
      showToast('Daily Bani Google Sheet synchronized live successfully!', 'success');
    }
    if (typeof state !== 'undefined' && state.activeSyncSheet === 1) {
      const cont = typeof document !== 'undefined' ? document.getElementById('main-content') : null;
      if (cont && typeof renderDailySheetsHub === 'function') {
        renderDailySheetsHub(cont);
      }
    }
    return parsed;
  } else {
    if (userTriggered && typeof showToast === 'function') {
      showToast('Using cached authoritative Daily Bani data (Google Sheet temporarily offline).', 'warning');
    }
    return getSheet1DailyBaniData();
  }
}

function toggleSheet1CapexOnly() {
  sheet1BaniState.filterCapexOnly = !sheet1BaniState.filterCapexOnly;
  if (typeof showToast === 'function') {
    showToast(sheet1BaniState.filterCapexOnly ? 'Filtered to Core Capex Schemes (PRI, DDC, BDC, APDP, ST).' : 'Showing All Schemes verbatim from Google Sheet.', 'info');
  }
  const cont = typeof document !== 'undefined' ? document.getElementById('main-content') : null;
  if (cont && typeof renderDailySheetsHub === 'function') {
    renderDailySheetsHub(cont);
  }
}

