async function syncLiveMLACDF(userTriggered = false) {
  const btn25 = document.getElementById('mla-sheet-sync-btn-25');
  const icon25 = document.getElementById('mla-sheet-spin-icon-25');
  const btn26 = document.getElementById('mla-sheet-sync-btn-26');
  const icon26 = document.getElementById('mla-sheet-spin-icon-26');

  [icon25, icon26].forEach(ic => { if (ic) ic.classList.add('fa-spin'); });
  [btn25, btn26].forEach(bt => { if (bt) bt.classList.add('opacity-75', 'pointer-events-none'); });

  if (userTriggered) {
    showToast('Connecting to Official MLA CDF Google Sheet...', 'info');
  }

  try {
    const res = await fetch(MLA_CDF_EXPORT_URL, { cache: 'no-store' });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const arrayBuffer = await res.arrayBuffer();
    if (!window.XLSX) throw new Error('SheetJS XLSX parser not loaded');
    const workbook = XLSX.read(arrayBuffer, { type: 'array' });

    let updated2025 = 0;
    let updated2026 = 0;

    workbook.SheetNames.forEach(sheetName => {
      const sName = sheetName.trim().toUpperCase();
      const ws = workbook.Sheets[sheetName];
      const data = XLSX.utils.sheet_to_json(ws, { header: 1 });

      if (sName.includes('2025-26') || sName === 'CDF 2025-26') {
        const parsed25 = [];
        for (let i = 4; i < data.length; i++) {
          const r = data[i];
          if (!r || !r[0] || isNaN(Number(r[0]))) continue;
          parsed25.push({
            sno: Number(r[0]),
            workCode: String(r[1] || '').trim(),
            name: String(r[2] || '').trim(),
            block: String(r[3] || 'Bani').trim(),
            constituency: String(r[4] || '63 - Bani').trim(),
            panchayat: String(r[5] || '').trim(),
            ddoCode: 'BNIRDD0001 BDO Bani',
            treasury: 'Bani',
            scheme: 'MLA CDF',
            estCost: Number(r[6]) || 0,
            aaaCost: Number(r[7]) || 0,
            aaaNoDated: String(r[8] || '-').trim(),
            outlay: Number(r[9]) || 0,
            fundsReleased2526: Number(r[10]) || 0,
            allotmentCost: Number(r[11]) || 0,
            expdt2526: Number(r[12]) || 0,
            amountMH8229: Number(r[10] || 0) - Number(r[12] || 0),
            contingency: Number(r[13]) || 0,
            totalExpdt: Number(r[14]) || 0,
            status: String(r[15] || 'In Progress').trim() === 'COMP' ? 'Completed' : String(r[15] || 'In Progress').trim(),
            startDate: String(r[16] || '-').trim(),
            compDate: String(r[17] || '-').trim(),
            remarks: String(r[18] || '-').trim(),
            jeTa: 'RDD Staff'
          });
        }
        if (parsed25.length > 0) {
          state.db.mlaWorks = parsed25;
          updated2025 = parsed25.length;
        }
      } else if (sName.includes('2026-27') || sName === 'CDF 2026-27') {
        const parsed26 = [];
        for (let i = 3; i < data.length; i++) {
          const r = data[i];
          if (!r || !r[0] || isNaN(Number(r[0]))) continue;

          let aaDateStr = String(r[11] || '').trim();
          if (!isNaN(Number(aaDateStr)) && Number(aaDateStr) > 40000) {
            const d = new Date((Number(aaDateStr) - 25569) * 86400 * 1000);
            aaDateStr = ('0' + d.getDate()).slice(-2) + '.' + ('0' + (d.getMonth() + 1)).slice(-2) + '.' + d.getFullYear();
          }

          const rawName = String(r[6] || '').trim();
          let pyt = 'Bani';
          const matchPyt = rawName.match(/PYT\.?\s*([A-Za-z0-9_\-\s]+?)(?:\s+BLOCK|\s+BANI|\.|$)/i);
          if (matchPyt && matchPyt[1]) pyt = matchPyt[1].trim().toUpperCase();

          parsed26.push({
            sno: Number(r[0]),
            constituency: String(r[1] || 'Bani').trim(),
            block: String(r[2] || 'Bani').trim(),
            agency: String(r[3] || 'RDD').trim(),
            mh: String(r[4] || '').trim(),
            workCode: String(r[5] || '').trim(),
            name: rawName,
            panchayat: pyt,
            type: String(r[7] || 'Construction').trim(),
            esttCost: Number(r[8]) || 0,
            proposedCost: Number(r[9]) || 0,
            aaOrder: String(r[10] || '').trim(),
            aaDate: aaDateStr,
            totalRelease: Number(r[12]) || 0,
            releasePercent: String(r[13] || '').trim(),
            beamsOrder: String(r[14] || '').trim(),
            tendered: String(r[15] || '').trim(),
            tenderDate: String(r[16] || '').trim(),
            l1Name: String(r[17] || '').trim(),
            allotted: String(r[18] || '').trim(),
            allotmentNoDate: String(r[19] || '').trim(),
            allotmentAmount: Number(r[20]) || 0,
            contractor: String(r[21] || '').trim(),
            started: String(r[22] || '').trim(),
            startDate: String(r[23] || '').trim(),
            completed: String(r[24] || '').trim(),
            compDate: String(r[25] || '').trim(),
            expdtAllotment: Number(r[26]) || 0,
            expdtContingency: Number(r[27]) || 0,
            totalExpdt: Number(r[28]) || 0,
            expdtTreasury: Number(r[29]) || 0,
            status: String(r[30] || 'In Progress').trim(),
            remarks: String(r[31] || '').trim()
          });
        }
        if (parsed26.length > 0) {
          state.db.mlaWorks2026 = parsed26;
          updated2026 = parsed26.length;
        }
      }
    });

    if (updated2025 > 0 || updated2026 > 0) {
      saveData();
      localStorage.setItem('bdo_bani_db_v2', JSON.stringify(state.db));
      refreshCurrentView();
      const timeStr = new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
      if (userTriggered || !window._bdoFirstMLASyncToastShown) {
        window._bdoFirstMLASyncToastShown = true;
        showToast(`MLA CDF Google Sheet Synced! (2025-26: ${updated2025} works, 2026-27: ${updated2026} works) at ${timeStr}`, 'success');
      }
    } else {
      if (userTriggered) showToast('Google Sheet read successfully, but no records found.', 'info');
    }
  } catch (err) {
    console.error('MLA Sheet Sync Error:', err);
    if (userTriggered) showToast('MLA Sheet Sync failed. Check connection.', 'error');
  } finally {
    [icon25, icon26].forEach(ic => { if (ic) ic.classList.remove('fa-spin'); });
    [btn25, btn26].forEach(bt => { if (bt) bt.classList.remove('opacity-75', 'pointer-events-none'); });
  }
}
window.syncLiveMLACDF = syncLiveMLACDF;

