                    (item.user || '').toLowerCase().includes(searchTxt) ||
                    (item.officerName || '').toLowerCase().includes(searchTxt) ||
                    (item.phone || '').toLowerCase().includes(searchTxt) ||
                    (item.action || '').toLowerCase().includes(searchTxt);
