function exportActivityLogsToCSV() {
  const logs = getStoredActivityLogs();
  if (!logs || logs.length === 0) {
    showToast('No logs to export', 'info');
    return;
  }
  let csv = 'Timestamp,Action,Details,Officer Name,User ID,Verified Mobile,Role,Device\n';
  logs.forEach(l => {
    const cleanDetails = (l.details || '').replace(/"/g, '""');
    const officer = (l.officerName || l.user || '').replace(/"/g, '""');
    const user = (l.user || '').replace(/"/g, '""');
    const phone = (l.phone || '').replace(/"/g, '""');
    csv += `"${l.timestamp}","${l.action}","${cleanDetails}","${officer}","${user}","${phone}","${l.role}","${l.device}"\n`;
  });
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `BDO_Bani_Audit_Register_${new Date().toISOString().slice(0, 10)}.csv`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  showToast('Official Audit Register exported to CSV!', 'success');
}
window.exportActivityLogsToCSV = exportActivityLogsToCSV;


// --- 2.5 GOOGLE AUTHENTICATOR (RFC 6238 TOTP) ZERO-SERVER 2FA SYSTEM ---
const GOOGLE_AUTH_SECRET = 'BDOBANIKATHUA234';
window.GOOGLE_AUTH_SECRET = GOOGLE_AUTH_SECRET;

function base32toUint8Array(base32) {
  const base32chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let bits = '';
  for (let i = 0; i < base32.length; i++) {
    const val = base32chars.indexOf(base32.charAt(i).toUpperCase());
    if (val === -1) continue;
    bits += val.toString(2).padStart(5, '0');
  }
  const bytes = [];
  for (let i = 0; i + 8 <= bits.length; i += 8) {
    bytes.push(parseInt(bits.substr(i, 8), 2));
  }
  return new Uint8Array(bytes);
}

async function verifyGoogleAuthTOTP(enteredCode, secret = GOOGLE_AUTH_SECRET) {
  if (!enteredCode) return false;
  const cleanCode = enteredCode.toString().trim();
  if (cleanCode.length !== 6) return false;
  try {
    const subtle = (window.crypto && window.crypto.subtle) ? window.crypto.subtle : null;
    if (!subtle) return false;
    const keyBytes = base32toUint8Array(secret);
    const cryptoKey = await subtle.importKey(
      'raw',
      keyBytes,
      { name: 'HMAC', hash: 'SHA-1' },
      false,
      ['sign']
    );
    const nowSec = Math.floor(Date.now() / 1000);
    // Check -4 to +2 windows (allows codes valid for up to 2.5 minutes to give users time to read & enter)
    for (let offset = -4; offset <= 2; offset++) {
      const epoch = Math.floor((nowSec + offset * 30) / 30);
      const buf = new ArrayBuffer(8);
      const view = new DataView(buf);
      view.setUint32(4, epoch, false);
      const sig = await subtle.sign('HMAC', cryptoKey, buf);
      const hmac = new Uint8Array(sig);
      const hmacOffset = hmac[hmac.length - 1] & 0xf;
      const binary = ((hmac[hmacOffset] & 0x7f) << 24) |
                     ((hmac[hmacOffset + 1] & 0xff) << 16) |
                     ((hmac[hmacOffset + 2] & 0xff) << 8) |
                     (hmac[hmacOffset + 3] & 0xff);
      const code = (binary % 1000000).toString().padStart(6, '0');
      if (code === cleanCode) return true;
    }
  } catch (e) {
    console.error('[2FA] TOTP verification error:', e);
  }
  return false;
}
window.verifyGoogleAuthTOTP = verifyGoogleAuthTOTP;

function copySetupKeyToClipboard() {
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(GOOGLE_AUTH_SECRET).then(() => {
      if (typeof showToast === 'function') showToast('Google Auth Key copied: ' + GOOGLE_AUTH_SECRET, 'success');
    }).catch(() => {
      prompt('Copy Google Authenticator Setup Key:', GOOGLE_AUTH_SECRET);
    });
  } else {
    prompt('Copy Google Authenticator Setup Key:', GOOGLE_AUTH_SECRET);
  }
}
window.copySetupKeyToClipboard = copySetupKeyToClipboard;

async function testGoogleAuthCode() {
  const inp = document.getElementById('test-google-auth-input');
  const res = document.getElementById('test-google-auth-result');
  if (!inp || !res) return;
  const val = inp.value.trim();
  if (!val) {
    res.innerHTML = '<span style="color: #f87171;">Please enter 6 digits.</span>';
    return;
  }
  const ok = await verifyGoogleAuthTOTP(val, GOOGLE_AUTH_SECRET);
  if (ok) {
    res.innerHTML = '<span style="color: #34d399; font-weight: bold;"><i class="fa-solid fa-circle-check"></i> Code Valid! Google Authenticator is paired and working 100%!</span>';
  } else {
    res.innerHTML = '<span style="color: #f87171; font-weight: bold;"><i class="fa-solid fa-circle-xmark"></i> Invalid code! Make sure phone time is set to Automatic.</span>';
  }
}
window.testGoogleAuthCode = testGoogleAuthCode;


