function saveAdminWhatsAppNumbers(num1, num2) {
  if (num1) localStorage.setItem('bdo_wa_admin_1', num1.trim());
  if (num2) localStorage.setItem('bdo_wa_admin_2', num2.trim());
}

function isWhatsAppConnected() {
  return localStorage.getItem('bdo_whatsapp_connected') === 'true';
}

function setWhatsAppConnected(val) {
  localStorage.setItem('bdo_whatsapp_connected', val ? 'true' : 'false');
}

function toggleWhatsAppAdvancedSettings() {
  window._waShowAdvanced = !window._waShowAdvanced;
  renderWhatsAppGatewayUI();
}
window.toggleWhatsAppAdvancedSettings = toggleWhatsAppAdvancedSettings;

window._waPollingInterval = null;

function getBackendBaseUrl() {
  if (window.location.protocol === 'http:' || window.location.protocol === 'https:') {
    return '';
  }
  return 'http://localhost:3000';
}

function startWhatsAppStatusPolling() {
  if (window._waPollingInterval) clearInterval(window._waPollingInterval);
  window._waPollingInterval = setInterval(async () => {
    try {
      const res = await fetch(getBackendBaseUrl() + '/api/whatsapp/status');
      const data = await res.json();
      if (data && data.connected) {
        clearInterval(window._waPollingInterval);
        window._waPollingInterval = null;
        setWhatsAppConnected(true);
        if (data.phone) localStorage.setItem('bdo_whatsapp_active_phone', data.phone);
        renderWhatsAppGatewayUI();
        if (typeof showToast === 'function') {
          showToast('🎉 WhatsApp Device Linked Successfully! Official Admin phone active.', 'success');
        }
        logUserActivity('WHATSAPP_LINKED', 'Admin WhatsApp (' + (data.phone || '+91 9697132353') + ') paired via live QR scan.', 'bdo.bani (Admin)', 'admin');
      }
    } catch (e) {}
  }, 2500);
}

function renderQRImageInContainer(qrDataUrl) {
  const qrContainer = document.getElementById('live-wa-qr-box');
  if (!qrContainer) return;

  qrContainer.innerHTML = `
    <div style="display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 14px; text-align: center; width: 100%;">
      <!-- High-contrast Crisp QR Code -->
      <div style="background: #ffffff !important; padding: 14px; border-radius: 16px; box-shadow: 0 12px 32px rgba(0,0,0,0.6); display: inline-block;">
        <img src="${qrDataUrl}" alt="WhatsApp Live QR Code" style="width: 250px; height: 250px; display: block; border-radius: 6px;" />
      </div>

      <!-- Pulsating Status Badge -->
      <div style="display: flex; align-items: center; gap: 8px; background: rgba(16, 185, 129, 0.15); border: 1px solid #10b981; color: #34d399; padding: 7px 16px; border-radius: 20px; font-size: 12px; font-weight: bold;">
        <span style="display: inline-block; width: 8px; height: 8px; border-radius: 50%; background: #34d399; box-shadow: 0 0 8px #34d399;"></span>
        <span>Waiting for WhatsApp QR Scan (Auto-detecting...)</span>
      </div>

      <!-- Instruction steps -->
      <div style="background: #0b1120; border: 1px solid #334155; border-radius: 12px; padding: 14px 18px; text-align: left; max-width: 440px; font-size: 12px; line-height: 1.6; color: #cbd5e1; width: 100%; box-sizing: border-box;">
        <div style="font-weight: 900; color: #ffffff; margin-bottom: 6px; display: flex; align-items: center; gap: 6px;">
          <i class="fa-brands fa-whatsapp" style="color: #25D366; font-size: 16px;"></i>
          <span>Official WhatsApp se Scan Karein:</span>
        </div>
        <div style="color: #94a3b8; font-size: 12px;">
          1. Apne phone me <strong>WhatsApp</strong> open karein.<br>
          2. <strong>Settings / Menu (⋮)</strong> ➔ <strong>Linked Devices</strong> par jayein.<br>
          3. <strong>"Link a Device"</strong> tap karein aur is QR code ko scan karein.<br>
          <span style="color: #34d399; font-weight: bold;">✨ Scan hote hi WhatsApp automatic Connected ho jayega!</span>
        </div>
      </div>

      <div style="display: flex; gap: 10px; margin-top: 2px;">
        <button type="button" onclick="fetchLiveWhatsAppQR()" style="background-color: #1e293b; color: #e2e8f0; border: 1px solid #475569; padding: 8px 16px; border-radius: 8px; font-size: 12px; font-weight: bold; cursor: pointer; display: flex; align-items: center; gap: 6px;">
          <i class="fa-solid fa-arrows-rotate"></i>
          <span>Regenerate QR</span>
        </button>
      </div>
    </div>
  `;
}

async function fetchLiveWhatsAppQR() {
  const qrContainer = document.getElementById('live-wa-qr-box');
  if (!qrContainer) return;

  qrContainer.innerHTML = `
    <div style="display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 30px 16px; text-align: center;">
      <div style="width: 44px; height: 44px; border: 4px solid #1e293b; border-top-color: #34d399; border-radius: 50%; animation: spin 1s linear infinite; margin-bottom: 14px;"></div>
      <p style="color: #ffffff; font-weight: bold; font-size: 14px; margin: 0;">Connecting to WhatsApp Web Engine...</p>
      <p style="color: #94a3b8; font-size: 12px; margin: 6px 0 0 0;">Generating fresh live QR Code via Baileys WebSocket...</p>
    </div>
  `;

  try {
    const res = await fetch(getBackendBaseUrl() + '/api/whatsapp/qr');
    const data = await res.json();

    if (data.connected) {
      setWhatsAppConnected(true);
      if (data.phone) localStorage.setItem('bdo_whatsapp_active_phone', data.phone);
      renderWhatsAppGatewayUI();
      if (typeof showToast === 'function') showToast('WhatsApp is already connected!', 'success');
      return;
    }

    if (data.qr) {
      renderQRImageInContainer(data.qr);
      startWhatsAppStatusPolling();
    } else {
      let count = 0;
      const pollQR = setInterval(async () => {
        count++;
        try {
          const pollRes = await fetch(getBackendBaseUrl() + '/api/whatsapp/status');
          const pollData = await pollRes.json();
          if (pollData.connected) {
            clearInterval(pollQR);
            setWhatsAppConnected(true);
            if (pollData.phone) localStorage.setItem('bdo_whatsapp_active_phone', pollData.phone);
            renderWhatsAppGatewayUI();
            if (typeof showToast === 'function') showToast('WhatsApp Linked Successfully!', 'success');
            return;
          }
          if (pollData.qr) {
            clearInterval(pollQR);
            renderQRImageInContainer(pollData.qr);
            startWhatsAppStatusPolling();
          } else if (count > 15) {
            clearInterval(pollQR);
            qrContainer.innerHTML = `
              <div style="padding: 20px; text-align: center; color: #fca5a5;">
                <p style="font-weight: bold; margin: 0 0 8px 0;">QR generation timed out.</p>
                <button type="button" onclick="fetchLiveWhatsAppQR()" style="background: #059669; color: white; border: none; padding: 8px 18px; border-radius: 8px; font-weight: bold; font-size: 12px; cursor: pointer;">
                  <i class="fa-solid fa-arrows-rotate"></i> Try Again
                </button>
              </div>
            `;
          }
        } catch (e) {}
      }, 1500);
    }
  } catch (err) {
    qrContainer.innerHTML = `
      <div style="padding: 20px; text-align: center; color: #fca5a5;">
        <p style="font-weight: bold; margin: 0 0 6px 0; font-size: 13px;">Backend Server not running on Port 3000</p>
        <p style="font-size: 11px; color: #94a3b8; margin: 0 0 12px 0;">Please run <code>node server.js</code> or launch via desktop app.</p>
        <button type="button" onclick="fetchLiveWhatsAppQR()" style="background: #059669; color: white; border: none; padding: 8px 18px; border-radius: 8px; font-weight: bold; font-size: 12px; cursor: pointer;">
          <i class="fa-solid fa-arrows-rotate"></i> Retry Connection
        </button>
      </div>
    `;
  }
}
window.fetchLiveWhatsAppQR = fetchLiveWhatsAppQR;

function openWhatsAppOtpAdminModal() {
  renderWhatsAppGatewayUI();
  const modal = document.getElementById('bdo-whatsapp-admin-modal');
  if (modal) {
    modal.style.setProperty('z-index', '999999', 'important');
    modal.style.setProperty('display', 'flex', 'important');
    modal.classList.remove('hidden');
  }

  fetch(getBackendBaseUrl() + '/api/whatsapp/status')
    .then(r => r.json())
    .then(data => {
      if (data && data.connected) {
        setWhatsAppConnected(true);
        if (data.phone) localStorage.setItem('bdo_whatsapp_active_phone', data.phone);
        renderWhatsAppGatewayUI();
      }
    })
    .catch(() => {});
}
window.openWhatsAppOtpAdminModal = openWhatsAppOtpAdminModal;

function closeWhatsAppOtpAdminModal() {
  if (window._waPollingInterval) {
    clearInterval(window._waPollingInterval);
    window._waPollingInterval = null;
  }
  const modal = document.getElementById('bdo-whatsapp-admin-modal');
  if (modal) {
    modal.classList.add('hidden');
    modal.style.setProperty('display', 'none', 'important');
  }
}
window.closeWhatsAppOtpAdminModal = closeWhatsAppOtpAdminModal;

function generateFreshWhatsAppQR() {
  fetchLiveWhatsAppQR();
}
window.generateFreshWhatsAppQR = generateFreshWhatsAppQR;

function confirmWhatsAppPairing(selectedNum) {
  const nums = getAdminWhatsAppNumbers();
  const linkedNum = selectedNum || nums[0];
  setWhatsAppConnected(true);
  localStorage.setItem('bdo_whatsapp_active_phone', linkedNum);
  logUserActivity('WHATSAPP_LINKED', 'Admin WhatsApp (' + linkedNum + ') paired and activated for live OTP dispatch.', 'bdo.bani (Admin)', 'admin');
  renderWhatsAppGatewayUI();
  showToast('WhatsApp Gateway successfully Linked to Admin (' + linkedNum + ')!', 'success');
}
window.confirmWhatsAppPairing = confirmWhatsAppPairing;

async function disconnectWhatsAppGateway() {
  if (confirm('Are you sure you want to disconnect this WhatsApp instance? Admin can re-link at any time.')) {
    if (window._waPollingInterval) {
      clearInterval(window._waPollingInterval);
      window._waPollingInterval = null;
    }
    try {
      await fetch(getBackendBaseUrl() + '/api/whatsapp/disconnect', { method: 'POST' });
    } catch(e) {}
    setWhatsAppConnected(false);
    localStorage.removeItem('bdo_whatsapp_active_phone');
    logUserActivity('WHATSAPP_DISCONNECTED', 'WhatsApp Gateway disconnected by admin.', 'bdo.bani (Admin)', 'admin');
    renderWhatsAppGatewayUI();
    showToast('WhatsApp instance disconnected. Click Generate WhatsApp QR Code to re-link.', 'warning');
  }
}
window.disconnectWhatsAppGateway = disconnectWhatsAppGateway;

