async function sendWhatsAppOtpToAdmin(otpCode, targetUser) {
  const nums = getAdminWhatsAppNumbers();
  const primaryPhone = nums[0].replace(/[^0-9]/g, '');
  const msgText = '🏛️ *OFFICIAL BDO BANI MONITORING PORTAL*\n\nYour 6-Digit WhatsApp Login OTP is: *' + otpCode + '*\n\nOfficer: ' + targetUser + '\nStatus: Live Verified\nValid for 10 minutes. Do not share.';

  console.log('[SECURITY-GATE] Dispatched 6-digit OTP to Admin (' + nums.join(', ') + ') for user: ' + targetUser);
  logUserActivity('OTP_DISPATCHED', 'Secure 6-digit WhatsApp Login OTP generated and dispatched to Admin (' + nums.join(', ') + ') for user: ' + targetUser, targetUser, 'auth');

  // 1. Live Baileys WhatsApp Engine (Primary Official Route)
  try {
    fetch(getBackendBaseUrl() + '/api/whatsapp/send-otp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ phone: primaryPhone, otp: otpCode, user: targetUser })
    }).catch(() => {});
  } catch(e) {}

  // 2. Automated CallMeBot Free WhatsApp Gateway (if API key saved)
  const cmbKey = localStorage.getItem('bdo_callmebot_key') || '';
  if (cmbKey) {
    try {
      fetch('https://api.callmebot.com/whatsapp.php?phone=' + primaryPhone + '&text=' + encodeURIComponent(msgText) + '&apikey=' + encodeURIComponent(cmbKey), { mode: 'no-cors' }).catch(() => {});
    } catch(e) {}
  }

  // 3. Automated Fast2SMS Quick Route (if API key saved)
  const fastKey = localStorage.getItem('bdo_fast2sms_key') || '';
  if (fastKey) {
    try {
      fetch('https://www.fast2sms.com/dev/bulkV2?authorization=' + encodeURIComponent(fastKey) + '&variables_values=' + encodeURIComponent(otpCode) + '&route=otp&numbers=' + primaryPhone, { mode: 'no-cors' }).catch(() => {});
    } catch(e) {}
  }
}
window.sendWhatsAppOtpToAdmin = sendWhatsAppOtpToAdmin;

