async function dispatchOfficerWhatsAppOtp() {
  const pending = window._pendingPortalLogin;
  if (!pending) return;

  const phoneInput = document.getElementById('officer-phone-input');
  const btn = document.getElementById('send-otp-btn');
  let rawPhone = (phoneInput ? phoneInput.value : '').replace(/[^0-9]/g, '');

  if (rawPhone.length < 10) {
    showToast('Please enter a valid 10-digit WhatsApp mobile number!', 'error');
    if (phoneInput) phoneInput.focus();
    return;
  }
  const cleanPhone = rawPhone.slice(-10); // last 10 digits
  pending.targetPhone = cleanPhone;

  // Generate 6-digit OTP
  const otpCode = Math.floor(100000 + Math.random() * 900000).toString();
  pending.otp = otpCode;
  pending.expiresAt = Date.now() + 10 * 60 * 1000; // 10 minutes validity

  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> <span>Sending WhatsApp OTP...</span>';
  }

  // 1. Dispatch via Local / Cloud Baileys Gateway Server
  let dispatchSuccess = false;
  try {
    const res = await fetch(getBackendBaseUrl() + '/api/whatsapp/send-otp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ phone: '91' + cleanPhone, otp: otpCode, user: pending.officer.name })
    });
    const data = await res.json();
    if (data && data.success) dispatchSuccess = true;
  } catch(e) {}

  // 2. Automated CallMeBot Free WhatsApp Fallback
  const cmbKey = localStorage.getItem('bdo_callmebot_key') || '';
  if (cmbKey) {
    const msg = `🏛️ *OFFICIAL BDO BANI MONITORING PORTAL*\n\nYour 6-Digit WhatsApp Login OTP is: *${otpCode}*\n\nOfficer: ${pending.officer.name}\nValid for 10 minutes.`;
    try {
      fetch('https://api.callmebot.com/whatsapp.php?phone=%2B91' + cleanPhone + '&text=' + encodeURIComponent(msg) + '&apikey=' + encodeURIComponent(cmbKey), { mode: 'no-cors' }).catch(() => {});
    } catch(e) {}
  }

  if (btn) {
    btn.disabled = false;
    btn.innerHTML = '<i class="fa-brands fa-whatsapp text-lg"></i> <span>Send OTP to my WhatsApp</span>';
  }

  // Log dispatch attempt
  logUserActivity('OTP_DISPATCHED', `Login OTP dispatched to WhatsApp +91 ${cleanPhone} for officer ${pending.officer.name} (${pending.user})`, pending.user, pending.role, cleanPhone);

  showToast(`WhatsApp OTP sent to +91 ${cleanPhone}! Check your WhatsApp.`, 'success');

  // Transition to Step 2: Code Entry
  const stepPhone = document.getElementById('otp-step-phone');
  const stepCode = document.getElementById('otp-step-code');
  const backLink = document.getElementById('otp-back-link');
  const phoneLabel = document.getElementById('otp-dispatched-phone-label');
  const codeInput = document.getElementById('login-otp-code');
  const errBox = document.getElementById('otp-error-msg');

  if (stepPhone) stepPhone.classList.add('hidden');
  if (stepCode) stepCode.classList.remove('hidden');
  if (backLink) backLink.classList.remove('hidden');
  if (phoneLabel) phoneLabel.innerText = `+91 ${cleanPhone} (${pending.officer.name})`;
  if (errBox) errBox.classList.add('hidden');
  if (codeInput) {
    codeInput.value = '';
    setTimeout(() => codeInput.focus(), 250);
  }
}
window.dispatchOfficerWhatsAppOtp = dispatchOfficerWhatsAppOtp;

