// OFFICIAL GOOGLE SHEET MONITORING FORMATS (4 CONSOLIDATED TABLES)
// DISTRICT CAPEX BUDGET (DCB) 2026-27 (KATHUA DISTRICT) - BDO BANI ONLY
// ============================================================================

function getGoogleSheetDistrictCapexMetrics() {
  const db = (typeof state !== 'undefined' && state.db) ? state.db : {};
  const priNew = Array.isArray(db.priNew) ? db.priNew : [];
  const ddc = Array.isArray(db.ddcWorks) ? db.ddcWorks : [];
  const bdc = Array.isArray(db.bdcWorks) ? db.bdcWorks : [];
  const priOngoing = Array.isArray(db.priOngoing) ? db.priOngoing : [];

  // Check live Google Sheet parsed cache
  const liveDCB = (typeof getSheet2DCBData === 'function') ? getSheet2DCBData() : null;
  const baniRowNew = (liveDCB && liveDCB.expdtNew && liveDCB.expdtNew.rows) ? liveDCB.expdtNew.rows.find(r => r.isBani) : null;
  const baniRowOngoing = (liveDCB && liveDCB.expdtOngoing && liveDCB.expdtOngoing.rows) ? liveDCB.expdtOngoing.rows.find(r => r.isBani) : null;
  const baniRowMeetingOngoing = (liveDCB && liveDCB.dcbMeetingOngoing && liveDCB.dcbMeetingOngoing.rows) ? liveDCB.dcbMeetingOngoing.rows.find(r => r.isBani) : null;
  const baniRowMeetingNew = (liveDCB && liveDCB.dcbMeetingNew && liveDCB.dcbMeetingNew.rows) ? liveDCB.dcbMeetingNew.rows.find(r => r.isBani) : null;

  // New Works Metrics
  const newWorksCount = baniRowNew ? (parseInt(baniRowNew.allottedWorks) || 97) : (priNew.length + ddc.length + bdc.length || 97);
  const newWorksComp = baniRowNew ? (parseInt(baniRowNew.completedWorks) || 27) : 27;
  const newApprovedTotal = 286.790;
  const newAllotmentCost = baniRowNew ? (parseFloat(baniRowNew.amountAllotted) || 224.495) : 224.495;
  const newExpdtOnDate = 0.000;
  const newTreasuryExpdt = 0.000;

  // Bills tracking for New Works (Sheet 3)
  const newBillsSubmittedXEN = baniRowNew ? (parseFloat(baniRowNew.billsSubXEN) || 34.480) : 34.480;
  const newBillsClearedXEN = baniRowNew ? (parseFloat(baniRowNew.billsClrXEN) || 34.480) : 34.480;
  const newBillsClearedBDO = baniRowNew ? (parseFloat(baniRowNew.billsClrBDO) || 20.390) : 20.390;
  const newBillsClearedTreasury = baniRowNew ? (parseFloat(baniRowNew.billsClrTreasury) || 20.390) : 20.390;
  const newPendingXEN = baniRowNew ? (parseFloat(baniRowNew.balXEN) || 0.000) : 0.000;
  const newPendingBDO = baniRowNew ? (parseFloat(baniRowNew.balBDO) || 14.090) : 14.090;
  const newPendingTreasury = baniRowNew ? (parseFloat(baniRowNew.balTreasury) || 0.000) : 0.000;
  const newRemarks = baniRowNew ? (baniRowNew.remarks || '20 work under PRI and 7 under DDC Physically completed') : '20 work under PRI and 7 under DDC Physically completed';

  // Table 1: Meeting New Works
  const meetingNonConstApproved = baniRowMeetingNew ? (parseInt(baniRowMeetingNew.nonConstApproved) || 0) : 0;
  const meetingNonConstCompleted = baniRowMeetingNew ? (parseInt(baniRowMeetingNew.nonConstCompleted) || 0) : 0;
  const meetingNonConstAmount = baniRowMeetingNew ? (parseFloat(baniRowMeetingNew.nonConstAmount) || 0.000) : 0.000;
  const meetingNonConstExpdt = baniRowMeetingNew ? (parseFloat(baniRowMeetingNew.nonConstExpdt) || 0.000) : 0.000;
  const meetingConstApproved = baniRowMeetingNew ? (parseInt(baniRowMeetingNew.constApproved) || newWorksCount) : newWorksCount;
  const meetingConstCompleted = baniRowMeetingNew ? (parseInt(baniRowMeetingNew.constCompleted) || newWorksComp) : newWorksComp;
  const meetingConstAmount = baniRowMeetingNew ? (parseFloat(baniRowMeetingNew.constAmount) || 286.790) : 286.790;
  const meetingConstAllotment = baniRowMeetingNew ? (parseFloat(baniRowMeetingNew.constAllotmentCost) || newAllotmentCost) : newAllotmentCost;
  const meetingConstExpdt = baniRowMeetingNew ? (parseFloat(baniRowMeetingNew.constExpdt) || 0.000) : 0.000;
  const meetingConstExpdtTreasury = baniRowMeetingNew ? (parseFloat(baniRowMeetingNew.constExpdtTreasury) || 0.000) : 0.000;
  const meetingNewRemarks = baniRowMeetingNew ? (baniRowMeetingNew.remarks || newRemarks) : newRemarks;

  // Ongoing Works Metrics
  const ongoingCount = baniRowOngoing ? (parseInt(baniRowOngoing.totalApproved || baniRowOngoing.allottedWorks) || 4) : 4;
  const ongoingComp = baniRowOngoing ? (parseInt(baniRowOngoing.completedWorks) || 4) : 4;
  const ongoingApproved = 21.560;
  const ongoingAllotment = baniRowOngoing ? (parseFloat(baniRowOngoing.amountAllotted) || 17.405) : 17.405;
  const ongoingExpdtOnDate = 3.380;
  const ongoingTreasuryExpdt = 3.380;
  const ongoingSubmittedXEN = baniRowOngoing ? (parseFloat(baniRowOngoing.billsSubXEN) || 3.380) : 3.380;
  const ongoingClearedXEN = baniRowOngoing ? (parseFloat(baniRowOngoing.billsClrXEN) || 3.380) : 3.380;
  const ongoingClearedBDO = baniRowOngoing ? (parseFloat(baniRowOngoing.billsClrBDO) || 3.380) : 3.380;
  const ongoingClearedTreasury = baniRowOngoing ? (parseFloat(baniRowOngoing.billsClrTreasury) || 3.380) : 3.380;
  const ongoingPendingXEN = baniRowOngoing ? (parseFloat(baniRowOngoing.balXEN) || 0.000) : 0.000;
  const ongoingPendingBDO = baniRowOngoing ? (parseFloat(baniRowOngoing.balBDO) || 0.000) : 0.000;
  const ongoingPendingTreasury = baniRowOngoing ? (parseFloat(baniRowOngoing.balTreasury) || 0.000) : 0.000;
  const ongoingRemarks = baniRowOngoing ? (baniRowOngoing.remarks || '4 works under PRI physically completed & 100% bills cleared') : '4 works under PRI physically completed & 100% bills cleared';

  // Table 2: Meeting Ongoing Works
  const meetingOngoingApproved = baniRowMeetingOngoing ? (parseInt(baniRowMeetingOngoing.approvedWorks) || 4) : 4;
  const meetingOngoingCompleted = baniRowMeetingOngoing ? (parseInt(baniRowMeetingOngoing.completedWorks) || 4) : 4;
  const meetingOngoingApprovedAmount = baniRowMeetingOngoing ? (parseFloat(baniRowMeetingOngoing.approvedAmount) || 21.560) : 21.560;
  const meetingOngoingAllotmentCost = baniRowMeetingOngoing ? (parseFloat(baniRowMeetingOngoing.allotmentCost) || 15.270) : 15.270;
  const meetingOngoingExpdt = baniRowMeetingOngoing ? (parseFloat(baniRowMeetingOngoing.expdtAsOnDate) || 1.930) : 1.930;
  const meetingOngoingTreasury = baniRowMeetingOngoing ? (parseFloat(baniRowMeetingOngoing.expdtTreasury) || 1.930) : 1.930;
  const meetingOngoingRemarks = baniRowMeetingOngoing ? (baniRowMeetingOngoing.remarks || ongoingRemarks) : ongoingRemarks;

  const todayDateStr = baniRowNew ? (baniRowNew.date || '19-11-2026') : '19-11-2026';
  const syncTimeStr = (typeof sheet2DCBState !== 'undefined' && sheet2DCBState.lastFetched) 
    ? sheet2DCBState.lastFetched 
    : (new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true }));

  return {
    newWorksCount,
    newWorksComp,
    newApprovedTotal,
    newAllotmentCost,
    newExpdtOnDate,
    newTreasuryExpdt,
    newBillsSubmittedXEN,
    newBillsClearedXEN,
    newBillsClearedBDO,
    newBillsClearedTreasury,
    newPendingXEN,
    newPendingBDO,
    newPendingTreasury,
    newRemarks,
    meetingNonConstApproved,
    meetingNonConstCompleted,
    meetingNonConstAmount,
    meetingNonConstExpdt,
    meetingConstApproved,
    meetingConstCompleted,
    meetingConstAmount,
    meetingConstAllotment,
    meetingConstExpdt,
    meetingConstExpdtTreasury,
    meetingNewRemarks,
    ongoingCount,
    ongoingComp,
    ongoingApproved,
    ongoingAllotment,
    ongoingExpdtOnDate,
    ongoingTreasuryExpdt,
    ongoingSubmittedXEN,
    ongoingClearedXEN,
    ongoingClearedBDO,
    ongoingClearedTreasury,
    ongoingPendingXEN,
    ongoingPendingBDO,
    ongoingPendingTreasury,
    ongoingRemarks,
    meetingOngoingApproved,
    meetingOngoingCompleted,
    meetingOngoingApprovedAmount,
    meetingOngoingAllotmentCost,
    meetingOngoingExpdt,
    meetingOngoingTreasury,
    meetingOngoingRemarks,
    todayDateStr,
    syncTimeStr
  };
}

