function copyOfficialFormatRow(type) {
  const m = getGoogleSheetDistrictCapexMetrics();
  let rowStr = '';
  if (type === 'new') {
    rowStr = [
      '2', m.todayDateStr, 'BDO-Bani', 'DDC/BDC/PRI/ABDP/APDP/Additionality',
      m.newWorksCount, m.newWorksComp, m.newAllotmentCost.toFixed(3),
      m.newBillsSubmittedXEN.toFixed(3), m.newBillsClearedXEN.toFixed(3),
      m.newBillsClearedBDO.toFixed(3), m.newBillsClearedTreasury.toFixed(3),
      m.newPendingXEN.toFixed(3), m.newPendingBDO.toFixed(3), m.newPendingTreasury.toFixed(3),
      '', m.newRemarks
    ].join('\t');
  } else {
    rowStr = [
      '2', m.todayDateStr, 'BDO-Bani',
      m.ongoingCount, m.ongoingCount, m.ongoingComp, m.ongoingAllotment.toFixed(3),
      m.ongoingSubmittedXEN.toFixed(3), m.ongoingClearedXEN.toFixed(3),
      m.ongoingClearedBDO.toFixed(3), m.ongoingClearedTreasury.toFixed(3),
      m.ongoingPendingXEN.toFixed(3), m.ongoingPendingBDO.toFixed(3), m.ongoingPendingTreasury.toFixed(3),
      '', m.ongoingRemarks
    ].join('\t');
  }

  navigator.clipboard.writeText(rowStr).then(() => {
    alert('BDO Bani row copied to clipboard! Open the Google Sheet and press Ctrl + V on the BDO Bani row.');
  }).catch(() => {
    prompt('Copy the row string below (Ctrl+C):', rowStr);
  });
}

