const DAILY_BANI_GOOGLE_SHEET_ID = '10vQXS5D36tGuvaBNEpe4xYBRs6RKUqv6BHq_eboosNQ';
const DAILY_BANI_GOOGLE_SHEET_EXPORT_URL = 'https://docs.google.com/spreadsheets/d/' + DAILY_BANI_GOOGLE_SHEET_ID + '/export?format=xlsx';
const DAILY_BANI_GOOGLE_SHEET_PAGE_URL = 'https://docs.google.com/spreadsheets/d/10vQXS5D36tGuvaBNEpe4xYBRs6RKUqv6BHq_eboosNQ/edit?gid=1884788730#gid=1884788730';

let dailyBaniLiveSheetData = null;

function parseDailyBaniCellNum(val) {
  if (val === undefined || val === null || val === '') return 0;
  const n = Number(val);
  return isNaN(n) ? 0 : n;
}

function parseDailyBaniFinRow(r) {
  if (!r) return { billsRecCount: 0, billsRecAmt: 0, billsClrCount: 0, billsClrAmt: 0, actualClrCount: 0, actualClrAmt: 0, tryPendingCount: 0, tryPendingAmt: 0, outlay: 0, funds: 0, allotCost: 0, expPct: 0 };
  return {
    billsRecCount: parseDailyBaniCellNum(r[3]),
    billsRecAmt: parseDailyBaniCellNum(r[4]),
    billsClrCount: parseDailyBaniCellNum(r[5]),
    billsClrAmt: parseDailyBaniCellNum(r[6]),
    actualClrCount: parseDailyBaniCellNum(r[7]),
    actualClrAmt: parseDailyBaniCellNum(r[8]),
    tryPendingCount: parseDailyBaniCellNum(r[9]),
    tryPendingAmt: parseDailyBaniCellNum(r[10]),
    outlay: parseDailyBaniCellNum(r[11]),
    funds: parseDailyBaniCellNum(r[12]),
    allotCost: parseDailyBaniCellNum(r[13]),
    expPct: parseDailyBaniCellNum(r[14])
  };
}

function parseDailyBaniPhysRow(r) {
  if (!r) return {
    approvedTotal: 0,
    nonConsttApproved: 0, nonConsttAA: 0, nonConsttGem: 0, nonConsttAllot: 0, nonConsttTU: 0, nonConsttCompPhys: 0, nonConsttCompBoth: 0, nonConsttInProg: 0, nonConsttNotStarted: 0, nonConsttDisp: 0,
    consttApproved: 0, consttAA: 0, consttTen: 0, consttAllot: 0, consttTU: 0, consttCompPhys: 0, consttCompBoth: 0, consttInProg: 0, consttNotStarted: 0, consttDisp: 0,
    totalApproved: 0, totalAA: 0, totalTen: 0, totalAllot: 0, totalTU: 0, totalCompPhys: 0, totalCompBoth: 0, totalInProg: 0, totalNotStarted: 0, totalDisp: 0
  };
  return {
    approvedTotal: parseDailyBaniCellNum(r[3]),
    nonConsttApproved: parseDailyBaniCellNum(r[4]),
    nonConsttAA: parseDailyBaniCellNum(r[5]),
    nonConsttGem: parseDailyBaniCellNum(r[6]),
    nonConsttAllot: parseDailyBaniCellNum(r[7]),
    nonConsttTU: parseDailyBaniCellNum(r[8]),
    nonConsttCompPhys: parseDailyBaniCellNum(r[9]),
    nonConsttCompBoth: parseDailyBaniCellNum(r[10]),
    nonConsttInProg: parseDailyBaniCellNum(r[11]),
    nonConsttNotStarted: parseDailyBaniCellNum(r[12]),
    nonConsttDisp: parseDailyBaniCellNum(r[13]),
    consttApproved: parseDailyBaniCellNum(r[14]),
    consttAA: parseDailyBaniCellNum(r[15]),
    consttTen: parseDailyBaniCellNum(r[16]),
    consttAllot: parseDailyBaniCellNum(r[17]),
    consttTU: parseDailyBaniCellNum(r[18]),
    consttCompPhys: parseDailyBaniCellNum(r[19]),
    consttCompBoth: parseDailyBaniCellNum(r[20]),
    consttInProg: parseDailyBaniCellNum(r[21]),
    consttNotStarted: parseDailyBaniCellNum(r[22]),
    consttDisp: parseDailyBaniCellNum(r[23]),
    totalApproved: parseDailyBaniCellNum(r[24]),
    totalAA: parseDailyBaniCellNum(r[25]),
    totalTen: parseDailyBaniCellNum(r[26]),
    totalAllot: parseDailyBaniCellNum(r[27]),
    totalTU: parseDailyBaniCellNum(r[28]),
    totalCompPhys: parseDailyBaniCellNum(r[29]),
    totalCompBoth: parseDailyBaniCellNum(r[30]),
    totalInProg: parseDailyBaniCellNum(r[31]),
    totalNotStarted: parseDailyBaniCellNum(r[32]),
    totalDisp: parseDailyBaniCellNum(r[33])
  };
}

function parseDailyBaniSheetData(finRows, physRows) {
  let lastUpdatedTime = '';
  if (finRows && finRows[7] && finRows[7][0]) lastUpdatedTime = String(finRows[7][0]).trim();
  if (!lastUpdatedTime && physRows && physRows[7] && physRows[7][0]) lastUpdatedTime = String(physRows[7][0]).trim();

  const schemes = {};
  DAILY_BANI_SCHEMES_DEF.forEach(def => {
    const sNo = def.sNo;
    const ongoingIdx = 4 + sNo; // Excel Rows 6 to 20
    const newIdx = 21 + sNo;    // Excel Rows 23 to 37
    const combIdx = 38 + sNo;   // Excel Rows 40 to 54

    const ongoingFin = parseDailyBaniFinRow(finRows ? finRows[ongoingIdx] : null);
    const ongoingPhys = parseDailyBaniPhysRow(physRows ? physRows[ongoingIdx] : null);

    const newFin = parseDailyBaniFinRow(finRows ? finRows[newIdx] : null);
    const newPhys = parseDailyBaniPhysRow(physRows ? physRows[newIdx] : null);

    const combFin = parseDailyBaniFinRow(finRows ? finRows[combIdx] : null);
    const combPhys = parseDailyBaniPhysRow(physRows ? physRows[combIdx] : null);

    schemes[def.id] = {
      def,
      ongoingFin,
      ongoingPhys,
      newFin,
      newPhys,
      combFin,
      combPhys
    };
  });

  const subTotalA = {
    fin: parseDailyBaniFinRow(finRows ? finRows[20] : null),
    phys: parseDailyBaniPhysRow(physRows ? physRows[20] : null)
  };

  const subTotalB = {
    fin: parseDailyBaniFinRow(finRows ? finRows[37] : null),
    phys: parseDailyBaniPhysRow(physRows ? physRows[37] : null)
  };

  const grandTotal = {
    fin: parseDailyBaniFinRow(finRows ? finRows[54] : null),
    phys: parseDailyBaniPhysRow(physRows ? physRows[54] : null)
  };

  return {
    lastUpdatedTime,
    schemes,
    subTotalA,
    subTotalB,
    grandTotal
  };
}

function getDailyBaniLiveSheetData() {
  if (window.dailyBaniLiveSheetData) return window.dailyBaniLiveSheetData;
  if (dailyBaniLiveSheetData) return dailyBaniLiveSheetData;
  try {
    const cached = localStorage.getItem('bdo_daily_bani_sheet_cache_v2');
    if (cached) {
      dailyBaniLiveSheetData = JSON.parse(cached);
      window.dailyBaniLiveSheetData = dailyBaniLiveSheetData;
      return dailyBaniLiveSheetData;
    }
  } catch (e) {}
  if (typeof window !== 'undefined' && window.DAILY_BANI_INITIAL_DATA) {
    dailyBaniLiveSheetData = window.DAILY_BANI_INITIAL_DATA;
    window.dailyBaniLiveSheetData = dailyBaniLiveSheetData;
    return dailyBaniLiveSheetData;
  }
  return null;
}

async function fetchDailyBaniGoogleSheet(userTriggered = false) {
  if (userTriggered && typeof showToast === 'function') {
    showToast('Connecting directly to Daily Bani Google Sheet...', 'info');
  }

  const refreshBtn = document.getElementById('btn-daily-bani-refresh');
  if (refreshBtn) {
    refreshBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin mr-1.5 text-blue-200"></i> <span>Fetching...</span>';
    refreshBtn.disabled = true;
  }

  let finRows = null;
  let physRows = null;

  // 1. Direct browser fetch from Google Sheets XLSX export
  try {
    const res = await fetch(DAILY_BANI_GOOGLE_SHEET_EXPORT_URL, { cache: 'no-store' });
    if (!res.ok) throw new Error('HTTP ' + res.status);
    const arrayBuffer = await res.arrayBuffer();
    if (!window.XLSX) throw new Error('SheetJS XLSX parser not loaded');
    const workbook = XLSX.read(arrayBuffer, { type: 'array' });
    const finSheet = workbook.Sheets['Financial-2026-27'];
    const physSheet = workbook.Sheets['Physical-2026-27'];
    if (finSheet && physSheet) {
      finRows = XLSX.utils.sheet_to_json(finSheet, { header: 1 });
      physRows = XLSX.utils.sheet_to_json(physSheet, { header: 1 });
    }
  } catch (directErr) {
    console.warn('[Daily Bani] Direct fetch note, checking server API route:', directErr.message);
  }

  // 2. Fallback to server-side API proxy route if direct fetch did not succeed
  if (!finRows || !physRows) {
    try {
      const apiRes = await fetch('/api/daily-bani-sheet', { cache: 'no-store' });
      if (apiRes.ok) {
        const json = await apiRes.json();
        if (json.success && json.finRows && json.physRows) {
          finRows = json.finRows;
          physRows = json.physRows;
        }
      }
    } catch (apiErr) {
      console.warn('[Daily Bani] Server API fetch note:', apiErr.message);
    }
  }

  if (finRows && physRows) {
    const parsed = parseDailyBaniSheetData(finRows, physRows);
    dailyBaniLiveSheetData = parsed;
    window.dailyBaniLiveSheetData = parsed;
    try {
      localStorage.setItem('bdo_daily_bani_sheet_cache_v2', JSON.stringify(parsed));
      localStorage.setItem('bdo_daily_bani_last_sync', new Date().toISOString());
    } catch (e) {}

    if (userTriggered && typeof showToast === 'function') {
      const timeStr = new Date().toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      showToast('Daily Bani Google Sheet Synced (' + timeStr + ')', 'success');
    }

    if (typeof state !== 'undefined' && state.currentTab === 'daily_bani_report') {
      renderDailyBaniReportView();
    }
    return parsed;
  } else {
    if (userTriggered && typeof showToast === 'function') {
      showToast('Offline mode: Showing cached Daily Bani figures.', 'warning');
    }
    if (refreshBtn) {
      refreshBtn.innerHTML = '<i class="fa-solid fa-arrows-rotate mr-1.5 text-blue-200"></i> <span>Refresh Live Sheet</span>';
      refreshBtn.disabled = false;
    }
    return null;
  }
}
window.fetchDailyBaniGoogleSheet = fetchDailyBaniGoogleSheet;
window.getDailyBaniLiveSheetData = getDailyBaniLiveSheetData;

function getDailyBaniDataset() {
  const live = getDailyBaniLiveSheetData();
  const schemesObj = live ? live.schemes : {};

  const rows = DAILY_BANI_SCHEMES_DEF.map(def => {
    const s = schemesObj[def.id];
    if (s) {
      return {
        def,
        ongoingPhys: s.ongoingPhys,
        ongoingFin: s.ongoingFin,
        newPhys: s.newPhys,
        newFin: s.newFin,
        combPhys: s.combPhys,
        combFin: s.combFin
      };
    }
    return {
      def,
      ongoingPhys: parseDailyBaniPhysRow(null),
      ongoingFin: parseDailyBaniFinRow(null),
      newPhys: parseDailyBaniPhysRow(null),
      newFin: parseDailyBaniFinRow(null),
      combPhys: parseDailyBaniPhysRow(null),
      combFin: parseDailyBaniFinRow(null)
    };
  });

  return rows;
}

function formatDailyCell(val, isAmt = false) {
  if (val === undefined || val === null || val === '') return '0';
  const str = String(val).trim();
  if (str === '' || str === '0') return '0';
  const num = Number(str);
  if (isNaN(num)) return str;
  if (num === 0) return '0';
  if (isAmt) {
    return (num % 1 !== 0 || str.includes('.')) ? num.toFixed(3) : String(num);
  }
  return String(num);
}

function setDailyBaniSchemePreset(preset) {
  if (!window.dailyBaniFilterState) return;
  const s = window.dailyBaniFilterState.selectedSchemes;
  DAILY_BANI_SCHEMES_DEF.forEach(def => {
    if (preset === 'active_capex_st') {
      s[def.id] = ['pri', 'ddc', 'bdc', 'apdp', 'abdp', 'ut_st_plan'].includes(def.id);
    } else if (preset === 'capex_mla_untied') {
      s[def.id] = ['pri', 'ddc', 'bdc', 'apdp', 'abdp', 'ut_st_plan', 'untied', 'mla_cdf'].includes(def.id);
    } else if (preset === 'all') {
      s[def.id] = true;
    } else if (preset === 'none') {
      s[def.id] = false;
    }
  });
  renderDailyBaniReportView();
}

function toggleDailyBaniScheme(schemeId) {
  if (!window.dailyBaniFilterState) return;
  const cur = !!window.dailyBaniFilterState.selectedSchemes[schemeId];
  window.dailyBaniFilterState.selectedSchemes[schemeId] = !cur;
  renderDailyBaniReportView();
}

function setDailyBaniViewMode(mode) {
  if (!window.dailyBaniFilterState) return;
  window.dailyBaniFilterState.viewMode = mode;
  renderDailyBaniReportView();
}

function toggleDailyBaniHideZeros() {
  if (!window.dailyBaniFilterState) return;
  window.dailyBaniFilterState.hideZeroRows = !window.dailyBaniFilterState.hideZeroRows;
  renderDailyBaniReportView();
}

function renderDailyBaniReportView(container) {
  const target = container || document.getElementById('main-content');
  if (!target) return;

  if (!window.dailyBaniFilterState) {
    window.dailyBaniFilterState = {
      viewMode: 'combined',
      selectedSchemes: {
        'ddc': true, 'bdc': true, 'pri': true, 'abdp': true, 'apdp': true,
        'untied': true, 'ele_edu': true, 'sec_edu': true, 'yss_distt': true,
        'ut_cd_pyt': true, 'ut_st_plan': true, 'ut_yss': true, 'pmagy': true,
        'mla_cdf': true, 'mplad': true
      },
      hideZeroRows: false,
      dataMode: 'live_gsheet'
    };
  }

  // Auto-fetch in background on view load if not already fetched in memory
  if (!window.dailyBaniLiveSheetData && typeof fetchDailyBaniGoogleSheet === 'function') {
    fetchDailyBaniGoogleSheet(false);
  }

  const { viewMode, selectedSchemes, hideZeroRows } = window.dailyBaniFilterState;
  const allRows = getDailyBaniDataset();
  const liveData = getDailyBaniLiveSheetData();

  // Filter rows based on checkbox selections
  const activeRows = allRows.filter(r => {
    if (!selectedSchemes[r.def.id]) return false;
    if (hideZeroRows && (r.combPhys.approvedTotal === 0 && r.combFin.outlay === 0 && r.combFin.billsRecCount === 0)) {
      return false;
    }
    return true;
  });

  // Calculate Sub-Totals & Grand Totals
  const ongoingSubTotalPhys = {};
  const ongoingSubTotalFin = {};
  const newSubTotalPhys = {};
  const newSubTotalFin = {};
  const grandTotalPhys = {};
  const grandTotalFin = {};

  const activeCount = Object.values(selectedSchemes).filter(Boolean).length;
  const isAllActive = activeCount === DAILY_BANI_SCHEMES_DEF.length;

  if (isAllActive && liveData && liveData.subTotalA && liveData.subTotalB && liveData.grandTotal) {
    // 100% exact verbatim totals directly from the Google Sheet
    Object.assign(ongoingSubTotalPhys, liveData.subTotalA.phys);
    Object.assign(ongoingSubTotalFin, liveData.subTotalA.fin);
    Object.assign(newSubTotalPhys, liveData.subTotalB.phys);
    Object.assign(newSubTotalFin, liveData.subTotalB.fin);
    Object.assign(grandTotalPhys, liveData.grandTotal.phys);
    Object.assign(grandTotalFin, liveData.grandTotal.fin);
  } else if (activeRows.length > 0) {
    const physKeys = Object.keys(activeRows[0].ongoingPhys);
    const finKeys = Object.keys(activeRows[0].ongoingFin);

    physKeys.forEach(k => {
      ongoingSubTotalPhys[k] = activeRows.reduce((sum, r) => sum + (r.ongoingPhys[k] || 0), 0);
      newSubTotalPhys[k] = activeRows.reduce((sum, r) => sum + (r.newPhys[k] || 0), 0);
      grandTotalPhys[k] = ongoingSubTotalPhys[k] + newSubTotalPhys[k];
    });

    finKeys.forEach(k => {
      if (k === 'expPct') return;
      ongoingSubTotalFin[k] = Number(activeRows.reduce((sum, r) => sum + (r.ongoingFin[k] || 0), 0).toFixed(3));
      newSubTotalFin[k] = Number(activeRows.reduce((sum, r) => sum + (r.newFin[k] || 0), 0).toFixed(3));
      grandTotalFin[k] = Number((ongoingSubTotalFin[k] + newSubTotalFin[k]).toFixed(3));
    });

    ongoingSubTotalFin.expPct = ongoingSubTotalFin.allotCost > 0 ? (ongoingSubTotalFin.billsClrAmt / ongoingSubTotalFin.allotCost) * 100 : 0;
    newSubTotalFin.expPct = newSubTotalFin.allotCost > 0 ? (newSubTotalFin.billsClrAmt / newSubTotalFin.allotCost) * 100 : 0;
    grandTotalFin.expPct = grandTotalFin.allotCost > 0 ? (grandTotalFin.billsClrAmt / grandTotalFin.allotCost) * 100 : 0;
  }
  const isSixActive = ['pri', 'ddc', 'bdc', 'apdp', 'abdp', 'ut_st_plan'].every(k => selectedSchemes[k]) &&
                      !['untied', 'ele_edu', 'sec_edu', 'yss_distt', 'ut_cd_pyt', 'ut_yss', 'pmagy', 'mla_cdf', 'mplad'].some(k => selectedSchemes[k]);

  // Overall KPI highlights
  const totalApprovedDisplay = grandTotalPhys.approvedTotal || 0;
  const totalCompDisplay = grandTotalPhys.totalCompPhys || 0;
  const totalInProgDisplay = grandTotalPhys.totalInProg || 0;
  const totalNotStartedDisplay = grandTotalPhys.totalNotStarted || 0;
  const totalAllotCostDisplay = grandTotalFin.allotCost || 0;
  const totalFundsDisplay = grandTotalFin.funds || 0;

  // Live timestamp formatted
  const now = new Date();
  const dayStr = String(now.getDate()).padStart(2, '0');
  const monthStr = String(now.getMonth() + 1).padStart(2, '0');
  const timeStr = String(now.getHours()).padStart(2, '0') + ':' + String(now.getMinutes()).padStart(2, '0') + ':' + String(now.getSeconds()).padStart(2, '0');
  const fullStamp = `${dayStr}/${monthStr}/${now.getFullYear()} ${timeStr}`;

  target.innerHTML = `
    <div class="space-y-6 max-w-[1950px] mx-auto pb-16 animate-fadeIn">
      
      <!-- TOP BANNER & CONTROLS -->
      <div style="background: linear-gradient(135deg, #0e2a47 0%, #173f67 50%, #091e33 100%); color: #ffffff;" class="p-6 rounded-2xl shadow-xl border border-blue-900/60 no-print">
        <div class="flex flex-wrap items-center justify-between gap-4">
          <div class="space-y-1.5">
            <div class="flex items-center gap-2">

              <span class="px-2.5 py-0.5 rounded-full bg-amber-400/20 text-amber-300 font-extrabold text-[11px] border border-amber-300/40">
                FY 2026–27
              </span>

              <span class="px-2.5 py-0.5 rounded-full bg-emerald-400/20 text-emerald-200 font-bold text-[11px] border border-emerald-400/40">
                <i class="fa-solid fa-cloud-arrow-down mr-1"></i> Live Google Sheet Fetched ${liveData && liveData.lastUpdatedTime ? '(' + liveData.lastUpdatedTime + ')' : ''}
              </span>
            </div>
            <h1 class="text-2xl md:text-3xl font-black text-white tracking-tight flex items-center gap-2.5">
              <span>Daily Bani — Status of Expenditure & Physical Progress</span>
            </h1>

          </div>

          <div class="flex flex-wrap items-center gap-2.5">
            <button id="btn-daily-bani-refresh" onclick="fetchDailyBaniGoogleSheet(true)" class="px-3.5 py-2.5 bg-blue-600 hover:bg-blue-500 text-white font-extrabold text-xs rounded-xl shadow-lg transition-all flex items-center gap-1.5 hover:scale-102 active:scale-95 cursor-pointer">
              <i class="fa-solid fa-arrows-rotate text-blue-200"></i>
              <span>Refresh Live Sheet</span>
            </button>
            <a href="https://docs.google.com/spreadsheets/d/10vQXS5D36tGuvaBNEpe4xYBRs6RKUqv6BHq_eboosNQ/edit?gid=1884788730#gid=1884788730" target="_blank" class="px-3.5 py-2.5 bg-white hover:bg-slate-100 text-slate-900 font-extrabold text-xs rounded-xl shadow-md transition-all flex items-center gap-1.5 hover:scale-102 active:scale-95 cursor-pointer">
              <i class="fa-solid fa-arrow-up-right-from-square text-emerald-600"></i>
              <span>Live Google Sheet</span>
            </a>
            <button onclick="exportDailyBaniExcel()" class="px-4 py-2.5 bg-emerald-600 hover:bg-emerald-500 text-white font-extrabold text-xs rounded-xl shadow-lg transition-all flex items-center gap-2 hover:scale-102 active:scale-95 cursor-pointer">
              <i class="fa-solid fa-file-excel text-emerald-200 text-sm"></i>
              <span>Export to Excel (.xlsx)</span>
            </button>
            <button onclick="window.print()" class="px-3.5 py-2.5 bg-slate-800 hover:bg-slate-700 text-white font-bold text-xs rounded-xl shadow-md border border-slate-600/50 transition-all flex items-center gap-1.5 hover:scale-102 active:scale-95 cursor-pointer">
              <i class="fa-solid fa-print text-slate-300"></i>
              <span>Print Abstract</span>
            </button>
          </div>
        </div>

        <!-- KPI SUMMARY STRIP -->
        <div class="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-6 gap-3 mt-5 pt-4 border-t border-blue-400/20 text-white">
          <div class="bg-white/10 backdrop-blur-sm rounded-xl p-3 border border-white/10">
            <div class="text-[10px] text-blue-200 font-bold uppercase tracking-wider">Approved Works</div>
            <div class="text-xl font-black mt-0.5 text-white flex items-baseline gap-1.5">
              <span>${totalApprovedDisplay}</span>
              <span class="text-[10px] font-normal text-blue-200">Works</span>
            </div>
            <div class="text-[9px] text-emerald-300 font-semibold mt-0.5">Checked Schemes Total</div>
          </div>

          <div class="bg-white/10 backdrop-blur-sm rounded-xl p-3 border border-white/10">
            <div class="text-[10px] text-emerald-200 font-bold uppercase tracking-wider">Completed</div>
            <div class="text-xl font-black mt-0.5 text-emerald-300 flex items-baseline gap-1.5">
              <span>${totalCompDisplay}</span>
              <span class="text-[10px] font-normal text-emerald-200">Works</span>
            </div>
            <div class="text-[9px] text-emerald-200/80 font-medium mt-0.5">${totalApprovedDisplay > 0 ? Math.round((totalCompDisplay / totalApprovedDisplay) * 100) : 0}% Completion Rate</div>
          </div>

          <div class="bg-white/10 backdrop-blur-sm rounded-xl p-3 border border-white/10">
            <div class="text-[10px] text-amber-200 font-bold uppercase tracking-wider">In Progress</div>
            <div class="text-xl font-black mt-0.5 text-amber-300 flex items-baseline gap-1.5">
              <span>${totalInProgDisplay}</span>
              <span class="text-[10px] font-normal text-amber-200">Works</span>
            </div>
            <div class="text-[9px] text-amber-200/80 font-medium mt-0.5">Execution Stage</div>
          </div>

          <div class="bg-white/10 backdrop-blur-sm rounded-xl p-3 border border-white/10">
            <div class="text-[10px] text-rose-200 font-bold uppercase tracking-wider">Not Started</div>
            <div class="text-xl font-black mt-0.5 text-rose-300 flex items-baseline gap-1.5">
              <span>${totalNotStartedDisplay}</span>
              <span class="text-[10px] font-normal text-rose-200">Works</span>
            </div>
            <div class="text-[9px] text-rose-200/80 font-medium mt-0.5">Tender / Allotment</div>
          </div>

          <div class="bg-white/10 backdrop-blur-sm rounded-xl p-3 border border-white/10">
            <div class="text-[10px] text-cyan-200 font-bold uppercase tracking-wider">Allotment Cost</div>
            <div class="text-xl font-black mt-0.5 text-cyan-300 flex items-baseline gap-1">
              <span class="text-xs">₹</span>
              <span>${totalAllotCostDisplay.toFixed(3)}</span>
              <span class="text-[10px] font-normal text-cyan-200">L</span>
            </div>
            <div class="text-[9px] text-blue-200/80 font-medium mt-0.5">Sum of Allotments</div>
          </div>

          <div class="bg-white/10 backdrop-blur-sm rounded-xl p-3 border border-white/10">
            <div class="text-[10px] text-purple-200 font-bold uppercase tracking-wider">Available Funds</div>
            <div class="text-xl font-black mt-0.5 text-purple-300 flex items-baseline gap-1">
              <span class="text-xs">₹</span>
              <span>${totalFundsDisplay.toFixed(2)}</span>
              <span class="text-[10px] font-normal text-purple-200">L</span>
            </div>
            <div class="text-[9px] text-purple-200/80 font-medium mt-0.5">Funds Released</div>
          </div>
        </div>
      </div>

      <!-- SCHEME FILTER CHECKBOX BAR (SMALL CHECKBOXES AT TOP) -->
      <div class="bg-white rounded-2xl shadow-sm border border-slate-200 p-5 no-print space-y-3">
        <div class="flex flex-wrap items-center justify-between gap-3 pb-2 border-b border-slate-100">
          <div class="flex items-center gap-2">
            <span class="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse"></span>
            <h2 class="text-sm font-black text-slate-800 uppercase tracking-wider">
              Dynamic Scheme Filter Controls (${activeCount} of ${DAILY_BANI_SCHEMES_DEF.length} Selected)
            </h2>

          </div>

          <!-- Preset Buttons -->
          <div class="flex flex-wrap items-center gap-2">
            <button onclick="setDailyBaniSchemePreset('active_capex_st')" class="px-2.5 py-1 text-xs font-bold rounded-lg border transition-all cursor-pointer ${isSixActive ? 'bg-emerald-600 text-white border-emerald-600 shadow' : 'bg-emerald-50 text-emerald-800 border-emerald-300 hover:bg-emerald-100'}">
              <i class="fa-solid fa-check-double text-[11px] mr-1"></i> Core Capex (6 Schemes)
            </button>
            <button onclick="setDailyBaniSchemePreset('capex_mla_untied')" class="px-2.5 py-1 text-xs font-bold rounded-lg border transition-all cursor-pointer bg-blue-50 text-blue-800 border-blue-300 hover:bg-blue-100">
              <i class="fa-solid fa-layer-group text-[11px] mr-1"></i> Capex + MLA + Untied (8)
            </button>
            <button onclick="setDailyBaniSchemePreset('all')" class="px-2.5 py-1 text-xs font-bold rounded-lg border transition-all cursor-pointer ${isAllActive ? 'bg-slate-800 text-white border-slate-800 shadow' : 'bg-slate-100 text-slate-700 border-slate-300 hover:bg-slate-200'}">
              Select All (15)
            </button>
            <button onclick="setDailyBaniSchemePreset('none')" class="px-2.5 py-1 text-xs font-bold rounded-lg border border-slate-200 text-slate-600 hover:bg-slate-100 transition-all cursor-pointer">
              Clear All
            </button>
            <label class="flex items-center gap-1.5 ml-2 text-xs font-bold text-slate-700 cursor-pointer bg-slate-50 hover:bg-slate-100 px-2.5 py-1 rounded-lg border border-slate-200">
              <input type="checkbox" ${hideZeroRows ? 'checked' : ''} onchange="toggleDailyBaniHideZeros()" class="w-3.5 h-3.5 text-blue-600 rounded cursor-pointer">
              <span>Hide 0-work rows</span>
            </label>
          </div>
        </div>

        <!-- 15 Small Scheme Checkboxes Grid -->
        <div class="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 lg:grid-cols-8 gap-2 pt-1">
          ${DAILY_BANI_SCHEMES_DEF.map(def => {
            const isChecked = !!selectedSchemes[def.id];
            const badgeColor = def.isCapex ? 'bg-emerald-100 text-emerald-800' : (def.id === 'untied' ? 'bg-amber-100 text-amber-800' : (def.id === 'mla_cdf' ? 'bg-purple-100 text-purple-800' : 'bg-slate-100 text-slate-700'));
            return `
              <label class="flex items-center gap-2 p-2 rounded-xl border transition-all cursor-pointer select-none ${isChecked ? 'bg-blue-50/80 border-blue-400 shadow-xs' : 'bg-white border-slate-200 hover:bg-slate-50 opacity-70'}">
                <input type="checkbox" ${isChecked ? 'checked' : ''} onchange="toggleDailyBaniScheme('${def.id}')" class="w-3.5 h-3.5 text-blue-600 rounded border-slate-300 cursor-pointer focus:ring-0">
                <div class="min-w-0 flex-1">
                  <div class="text-[11px] font-bold text-slate-900 truncate flex items-center justify-between gap-1">
                    <span>${def.name}</span>
                    <span class="text-[9px] px-1 py-0.2 rounded font-extrabold ${badgeColor}">${def.defaultWorks > 0 ? def.defaultWorks : '0'}</span>
                  </div>
                </div>
              </label>
            `;
          }).join('')}
        </div>
      </div>

      <!-- VIEW SELECTOR TABS -->
      <div class="flex flex-wrap items-center justify-between gap-3 no-print">
        <div class="flex items-center p-1 bg-slate-200/80 rounded-xl shadow-inner border border-slate-300/60">
          <button onclick="setDailyBaniViewMode('combined')" class="px-4 py-2 text-xs font-black rounded-lg transition-all flex items-center gap-2 cursor-pointer ${viewMode === 'combined' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-600 hover:text-slate-900'}">
            <i class="fa-solid fa-table-list text-blue-600"></i>
            <span>Both Sheets (Combined Abstract)</span>
          </button>
          <button onclick="setDailyBaniViewMode('financial')" class="px-4 py-2 text-xs font-black rounded-lg transition-all flex items-center gap-2 cursor-pointer ${viewMode === 'financial' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-600 hover:text-slate-900'}">
            <i class="fa-solid fa-coins text-amber-500"></i>
            <span>Financial Progress (2026–27)</span>
          </button>
          <button onclick="setDailyBaniViewMode('physical')" class="px-4 py-2 text-xs font-black rounded-lg transition-all flex items-center gap-2 cursor-pointer ${viewMode === 'physical' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-600 hover:text-slate-900'}">
            <i class="fa-solid fa-helmet-safety text-emerald-600"></i>
            <span>Physical Progress (2026–27)</span>
          </button>
        </div>


      </div>

      <!-- TABLE CONTAINER -->
      <div class="space-y-8">
        ${(viewMode === 'combined' || viewMode === 'financial') ? renderFinancialTableHTML(activeRows, ongoingSubTotalFin, newSubTotalFin, grandTotalFin, fullStamp) : ''}
        ${(viewMode === 'combined' || viewMode === 'physical') ? renderPhysicalTableHTML(activeRows, ongoingSubTotalPhys, newSubTotalPhys, grandTotalPhys, fullStamp) : ''}
      </div>

    </div>
  `;
}

// ----------------------------------------------------------------------------
// TABLE 1: FINANCIAL-2026-27 (EXACT VERBATIM GOOGLE SHEET HEADINGS)
// ----------------------------------------------------------------------------
function renderFinancialTableHTML(rows, subTotalA, subTotalB, grandTotal, fullStamp) {
  // Single Unified Professional Executive Color: Deep Navy
  const thBg = 'background-color: #0e2a47; color: #ffffff; border-color: #244970;';
  const thRow1 = thBg;
  const thRow2 = thBg;

  // Left frozen columns: S. No. and Scheme
  const thCol1 = 'min-width: 55px; max-width: 55px; ' + thBg;
  const thCol2 = 'min-width: 200px; max-width: 220px; ' + thBg;

  return `
    <div class="bg-white rounded-2xl border border-slate-300 shadow-md overflow-hidden">
      <!-- Title Bar matching Google Sheet Row 1 & 2 -->
      <div style="background-color: #0e2a47;" class="p-4 text-white flex flex-wrap items-center justify-between gap-3 border-b border-blue-900">
        <div>
          <h2 class="text-base md:text-lg font-black tracking-wide text-white">
            Status of Expenditure under DCB / UT, 2026-27 (RDD Sector Only)
          </h2>
          
        </div>
        <div class="flex items-center gap-2">
          <div class="px-3 py-1 bg-white/10 text-cyan-300 rounded-lg text-xs font-bold border border-cyan-300/30 font-mono">
            Updated: <strong class="text-white">${fullStamp}</strong>
          </div>
          <span class="px-3 py-1 bg-white/10 text-amber-300 rounded-lg text-xs font-black border border-amber-300/30">
            (₹. in Lakhs)
          </span>
        </div>
      </div>

      <!--  Scroll Container -->
      <div class="overflow-x-auto border border-slate-200 custom-scrollbar">
        <table class="w-full text-xs text-left border-collapse font-sans min-w-[1450px]">
          <!-- Table Headings with Single Unified Color & Strict  -->
          <thead class="text-[11px] font-black text-center shadow">
            <tr style="height: 37px;">
              <th rowspan="2" style="${thCol1}" class="p-2 border border-slate-600 text-center">
                S. No.
              </th>
              <th rowspan="2" style="${thCol2}" class="p-2 border border-slate-600 text-left">
                Scheme
              </th>
              <th colspan="2" style="${thRow1}" class="p-2 border border-slate-600">
                From XEN REW Kathua
              </th>
              <th colspan="2" style="${thRow1}" class="p-2 border border-slate-600">
                Exp.(Actual + Booked)
              </th>
              <th colspan="2" style="${thRow1}" class="p-2 border border-slate-600">
                Actual Exped.
              </th>
              <th colspan="2" style="${thRow1}" class="p-2 border border-slate-600">
                Booked Expend in Try.
              </th>
              <th rowspan="2" style="${thRow1} min-w-[105px];" class="p-2 border border-slate-600">
                Approved Outlay 2026-27
              </th>
              <th rowspan="2" style="${thRow1} min-w-[110px];" class="p-2 border border-slate-600">
                Total Funds Received ( Availability)
              </th>
              <th rowspan="2" style="${thRow1} min-w-[105px];" class="p-2 border border-slate-600">
                Total Allotment Cost
              </th>
              <th rowspan="2" style="${thRow1} min-w-[105px];" class="p-2 border border-slate-600">
                Expenditure in %age(wrt Allotment)
              </th>
            </tr>
            <tr style="height: 38px;" class="text-[10px]">
              <th style="${thRow2} min-w-[85px];" class="p-1.5 border border-slate-600">No. of Bills Received</th>
              <th style="${thRow2} min-w-[95px];" class="p-1.5 border border-slate-600">Amount of Bills received</th>
              <th style="${thRow2} min-w-[85px];" class="p-1.5 border border-slate-600">No. of Bills Cleared</th>
              <th style="${thRow2} min-w-[125px];" class="p-1.5 border border-slate-600">Amount of Bills Cleared & Forwarded to Treasury</th>
              <th style="${thRow2} min-w-[85px];" class="p-1.5 border border-slate-600">No. of Bills Cleared</th>
              <th style="${thRow2} min-w-[95px];" class="p-1.5 border border-slate-600">Amount of Bills Cleared</th>
              <th style="${thRow2} min-w-[95px];" class="p-1.5 border border-slate-600">No. of Bills Pending for clearance</th>
              <th style="${thRow2} min-w-[115px];" class="p-1.5 border border-slate-600">Amount of Bills Pending for clearance</th>
            </tr>
          </thead>

          <tbody class="divide-y divide-slate-200 text-slate-800 text-[11px]">

            <!-- ================= SECTION A: ONGOING WORKS ================= -->
            <tr class="bg-blue-100/90 font-black text-blue-950 border-y-2 border-blue-400">
              <td style="background-color: #dbeafe;" class="p-2 text-center font-bold">A</td>
              <td style="background-color: #dbeafe;" colspan="13" class="p-2 uppercase tracking-wider text-xs">
                Ongoing Works
              </td>
            </tr>
            ${rows.map((r, i) => {
              const rowBg = r.def.id === 'pri' ? '#fef3c7' : '#ffffff';
              return `
                <tr style="background-color: ${rowBg};" class="hover:bg-amber-100/80 transition-colors">
                  <td style="background-color: ${rowBg};" class="p-2 text-center text-slate-700 font-mono font-bold border-r border-slate-200">
                    ${r.def.sNo}
                  </td>
                  <td style="background-color: ${rowBg};" class="p-2 font-bold text-slate-900 border-r border-slate-200">
                    <span>${r.def.name}</span>
                    ${r.def.id === 'pri' ? '<span class="ml-1.5 px-1.5 py-0.5 rounded text-[9px] bg-amber-200 text-amber-900 font-black border border-amber-300">4 Works</span>' : ''}
                  </td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.ongoingFin.billsRecCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.ongoingFin.billsRecAmt, true)}</td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.ongoingFin.billsClrCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.ongoingFin.billsClrAmt, true)}</td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.ongoingFin.actualClrCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.ongoingFin.actualClrAmt, true)}</td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.ongoingFin.tryPendingCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.ongoingFin.tryPendingAmt, true)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono font-bold">${formatDailyCell(r.ongoingFin.outlay, true)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono font-bold">${formatDailyCell(r.ongoingFin.funds, true)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono font-bold text-blue-900">${formatDailyCell(r.ongoingFin.allotCost, true)}</td>
                  <td class="p-2 text-center font-bold ${r.ongoingFin.expPct > 0 ? 'text-emerald-700' : 'text-slate-400'}">${r.ongoingFin.expPct > 0 ? r.ongoingFin.expPct.toFixed(1) + '%' : '0%'}</td>
                </tr>
              `;
            }).join('')}
            <!-- Sub-Total (A) -->
            <tr style="background-color: #0e2a47; color: #ffffff;" class="font-black border-y-2 border-slate-900 text-xs">
              <td style="background-color: #0e2a47;" class="p-2.5 text-center"></td>
              <td style="background-color: #0e2a47;" class="p-2.5 uppercase tracking-wide border-r border-slate-700 text-amber-300">
                Sub-Total (A)
              </td>
              <td class="p-2.5 text-center border-r border-slate-700">${formatDailyCell(subTotalA.billsRecCount)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono">${formatDailyCell(subTotalA.billsRecAmt, true)}</td>
              <td class="p-2.5 text-center border-r border-slate-700">${formatDailyCell(subTotalA.billsClrCount)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono">${formatDailyCell(subTotalA.billsClrAmt, true)}</td>
              <td class="p-2.5 text-center border-r border-slate-700">${formatDailyCell(subTotalA.actualClrCount)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono">${formatDailyCell(subTotalA.actualClrAmt, true)}</td>
              <td class="p-2.5 text-center border-r border-slate-700">${formatDailyCell(subTotalA.tryPendingCount)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono">${formatDailyCell(subTotalA.tryPendingAmt, true)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono font-bold">${formatDailyCell(subTotalA.outlay, true)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono font-bold">${formatDailyCell(subTotalA.funds, true)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono text-cyan-300 font-black">${formatDailyCell(subTotalA.allotCost, true)}</td>
              <td class="p-2.5 text-center text-amber-300 font-black">${subTotalA.expPct > 0 ? subTotalA.expPct.toFixed(1) + '%' : '0%'}</td>
            </tr>

            <!-- ================= SECTION B: NEW WORKS ================= -->
            <tr class="bg-emerald-100/90 font-black text-emerald-950 border-y-2 border-emerald-400">
              <td style="background-color: #d1fae5;" class="p-2 text-center font-bold">B</td>
              <td style="background-color: #d1fae5;" colspan="13" class="p-2 uppercase tracking-wider text-xs">
                New Works
              </td>
            </tr>
            ${rows.map((r, i) => {
              const rowBg = r.def.id === 'pri' ? '#ecfdf5' : '#ffffff';
              return `
                <tr style="background-color: ${rowBg};" class="hover:bg-slate-100/80 transition-colors">
                  <td style="background-color: ${rowBg};" class="p-2 text-center text-slate-600 font-mono font-bold border-r border-slate-200">
                    ${r.def.sNo}
                  </td>
                  <td style="background-color: ${rowBg};" class="p-2 font-bold text-slate-900 border-r border-slate-200">
                    <span>${r.def.name}</span>
                    ${r.def.id === 'pri' ? '<span class="ml-1.5 px-1 py-0.2 rounded text-[9px] bg-emerald-200 text-emerald-900 font-black">78 Works</span>' : ''}
                  </td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.newFin.billsRecCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.newFin.billsRecAmt, true)}</td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.newFin.billsClrCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.newFin.billsClrAmt, true)}</td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.newFin.actualClrCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.newFin.actualClrAmt, true)}</td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.newFin.tryPendingCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.newFin.tryPendingAmt, true)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono font-bold">${formatDailyCell(r.newFin.outlay, true)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono font-bold">${formatDailyCell(r.newFin.funds, true)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono font-bold text-emerald-900">${formatDailyCell(r.newFin.allotCost, true)}</td>
                  <td class="p-2 text-center font-bold ${r.newFin.expPct > 0 ? 'text-emerald-700' : 'text-slate-400'}">${r.newFin.expPct > 0 ? r.newFin.expPct.toFixed(1) + '%' : '0%'}</td>
                </tr>
              `;
            }).join('')}
            <!-- Sub-Total (B) -->
            <tr style="background-color: #0e2a47; color: #ffffff;" class="font-black border-y-2 border-slate-900 text-xs">
              <td style="background-color: #0e2a47;" class="p-2.5 text-center"></td>
              <td style="background-color: #0e2a47;" class="p-2.5 uppercase tracking-wide border-r border-slate-700 text-emerald-300">
                Sub-Total (B)
              </td>
              <td class="p-2.5 text-center border-r border-slate-700">${formatDailyCell(subTotalB.billsRecCount)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono">${formatDailyCell(subTotalB.billsRecAmt, true)}</td>
              <td class="p-2.5 text-center border-r border-slate-700">${formatDailyCell(subTotalB.billsClrCount)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono">${formatDailyCell(subTotalB.billsClrAmt, true)}</td>
              <td class="p-2.5 text-center border-r border-slate-700">${formatDailyCell(subTotalB.actualClrCount)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono">${formatDailyCell(subTotalB.actualClrAmt, true)}</td>
              <td class="p-2.5 text-center border-r border-slate-700">${formatDailyCell(subTotalB.tryPendingCount)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono">${formatDailyCell(subTotalB.tryPendingAmt, true)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono font-bold">${formatDailyCell(subTotalB.outlay, true)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono font-bold">${formatDailyCell(subTotalB.funds, true)}</td>
              <td class="p-2.5 text-right border-r border-slate-700 font-mono text-cyan-300 font-black">${formatDailyCell(subTotalB.allotCost, true)}</td>
              <td class="p-2.5 text-center text-emerald-300 font-black">${subTotalB.expPct > 0 ? subTotalB.expPct.toFixed(1) + '%' : '0%'}</td>
            </tr>

            <!-- ================= SECTION C: ONGOING + NEW WORKS ================= -->
            <tr class="bg-purple-100/90 font-black text-purple-950 border-y-2 border-purple-400">
              <td style="background-color: #ede9fe;" class="p-2 text-center font-bold">C</td>
              <td style="background-color: #ede9fe;" colspan="13" class="p-2 uppercase tracking-wider text-xs">
                Ongoing+New Works (Consolidated)
              </td>
            </tr>
            ${rows.map((r, i) => {
              const rowBg = r.def.id === 'pri' ? '#f5f3ff' : '#ffffff';
              return `
                <tr style="background-color: ${rowBg};" class="hover:bg-slate-100/80 transition-colors">
                  <td style="background-color: ${rowBg};" class="p-2 text-center text-slate-600 font-mono font-bold border-r border-slate-200">
                    ${r.def.sNo}
                  </td>
                  <td style="background-color: ${rowBg};" class="p-2 font-bold text-slate-900 border-r border-slate-200">
                    <span>${r.def.name}</span>
                    ${r.def.id === 'pri' ? '<span class="ml-1.5 px-1.5 py-0.2 rounded text-[9px] bg-indigo-200 text-indigo-950 font-black">4 + 78 = 82 Works</span>' : ''}
                  </td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.combFin.billsRecCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.combFin.billsRecAmt, true)}</td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.combFin.billsClrCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.combFin.billsClrAmt, true)}</td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.combFin.actualClrCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.combFin.actualClrAmt, true)}</td>
                  <td class="p-2 text-center border-r border-slate-200">${formatDailyCell(r.combFin.tryPendingCount)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono">${formatDailyCell(r.combFin.tryPendingAmt, true)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono font-bold">${formatDailyCell(r.combFin.outlay, true)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono font-bold">${formatDailyCell(r.combFin.funds, true)}</td>
                  <td class="p-2 text-right border-r border-slate-200 font-mono font-black text-blue-950">${formatDailyCell(r.combFin.allotCost, true)}</td>
                  <td class="p-2 text-center font-bold ${r.combFin.expPct > 0 ? 'text-indigo-800' : 'text-slate-400'}">${r.combFin.expPct > 0 ? r.combFin.expPct.toFixed(1) + '%' : '0%'}</td>
                </tr>
              `;
            }).join('')}
            <!-- Grand Total (A+B) -->
            <tr style="background-color: #06192d; color: #ffffff;" class="font-black border-t-2 border-slate-900 text-xs shadow-lg">
              <td style="background-color: #06192d;" class="p-3 text-center text-amber-400">★</td>
              <td style="background-color: #06192d;" class="p-3 uppercase tracking-wide border-r border-slate-700 text-amber-300">
                G-Total (A+B)
              </td>
              <td class="p-3 text-center border-r border-slate-700 text-cyan-300">${formatDailyCell(grandTotal.billsRecCount)}</td>
              <td class="p-3 text-right border-r border-slate-700 font-mono text-cyan-300">${formatDailyCell(grandTotal.billsRecAmt, true)}</td>
              <td class="p-3 text-center border-r border-slate-700 text-emerald-300">${formatDailyCell(grandTotal.billsClrCount)}</td>
              <td class="p-3 text-right border-r border-slate-700 font-mono text-emerald-300">${formatDailyCell(grandTotal.billsClrAmt, true)}</td>
              <td class="p-3 text-center border-r border-slate-700 text-teal-300">${formatDailyCell(grandTotal.actualClrCount)}</td>
              <td class="p-3 text-right border-r border-slate-700 font-mono text-teal-300">${formatDailyCell(grandTotal.actualClrAmt, true)}</td>
              <td class="p-3 text-center border-r border-slate-700 text-amber-300">${formatDailyCell(grandTotal.tryPendingCount)}</td>
              <td class="p-3 text-right border-r border-slate-700 font-mono text-amber-300">${formatDailyCell(grandTotal.tryPendingAmt, true)}</td>
              <td class="p-3 text-right border-r border-slate-700 font-mono text-indigo-300">${formatDailyCell(grandTotal.outlay, true)}</td>
              <td class="p-3 text-right border-r border-slate-700 font-mono text-purple-300">${formatDailyCell(grandTotal.funds, true)}</td>
              <td class="p-3 text-right border-r border-slate-700 font-mono text-yellow-300 font-black text-sm">${formatDailyCell(grandTotal.allotCost, true)}</td>
              <td class="p-3 text-center text-amber-300 font-black text-sm">${grandTotal.expPct > 0 ? grandTotal.expPct.toFixed(1) + '%' : '0%'}</td>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  `;
}

