// TREASURY BILL CLEARANCE & 1-CLICK BOOKING MANAGER
// =============================================================

window.treasuryHubState = window.treasuryHubState || {
  activeTab: 'pending', // 'pending' | 'cleared' | 'book_new'
  selectedScheme: 'ALL',
  searchQuery: '',
  selectedPanchayat: 'ALL'
};

function getAllTreasuryWorks() {
  if (!state.db) return [];
  const list = [];
  const map = [
    { key: 'priOngoing', label: 'PRI Capex (Ongoing)', scheme: 'PRI', cat: 'priOngoing', color: 'blue' },
    { key: 'priNew', label: 'PRI Capex (New)', scheme: 'PRI', cat: 'priNew', color: 'indigo' },
    { key: 'ddcWorks', label: 'DDC Capex', scheme: 'DDC', cat: 'ddcWorks', color: 'purple' },
    { key: 'bdcWorks', label: 'BDC Capex', scheme: 'BDC', cat: 'bdcWorks', color: 'amber' },
    { key: 'apdpWorks', label: 'APDP Capex', scheme: 'APDP', cat: 'apdpWorks', color: 'teal' },
    { key: 'stWorks', label: 'UT Capex (ST Plan)', scheme: 'ST', cat: 'stWorks', color: 'orange' },
    { key: 'mlaWorks', label: 'MLA CDF (2025-26)', scheme: 'MLA', cat: 'mlaWorks', color: 'rose' },
    { key: 'mlaWorks2026', label: 'MLA CDF (2026-27)', scheme: 'MLA', cat: 'mlaWorks2026', color: 'emerald' }
  ];
  map.forEach(m => {
    (state.db[m.key] || []).forEach((w, idx) => {
      const code = (w.workCode || w.code || (m.key.startsWith('mla') ? `MLA-${m.key === 'mlaWorks2026' ? '26' : '25'}-${w.sno || (idx + 1)}` : `WORK-${idx+1}`)).trim();
      list.push({
        ...w,
        workCode: code,
        allotmentCost: w.allotmentCost != null ? Number(w.allotmentCost) : (Number(w.amountMH8229) || Number(w.fundsReleased2526) || 0),
        fundsReleased: w.fundsReleased != null ? Number(w.fundsReleased) : (Number(w.fundsReleased2526) || 0),
        expdtBookedTreasury: Number(w.expdtBookedTreasury != null ? w.expdtBookedTreasury : (w.expdtTreasury || 0)),
        actualExpdtTotal: Number(w.actualExpdtTotal != null ? w.actualExpdtTotal : (w.expdt8229 || 0)),
        _category: m.cat,
        _schemeKey: m.key,
        _schemeLabel: m.label,
        _shortScheme: m.scheme,
        _color: m.color,
        _schemeSno: w.sno || (idx + 1)
      });
    });
  });
  return list;
}

function setTreasuryHubTab(tabName) {
  window.treasuryHubState.activeTab = tabName;
  const container = document.getElementById('main-content');
  if (container) renderTreasuryBillHub(container);
}

function setTreasurySchemeFilter(sch) {
  window.treasuryHubState.selectedScheme = sch;
  const container = document.getElementById('main-content');
  if (container) renderTreasuryBillHub(container);
}

function setTreasurySearchQuery(q) {
  window.treasuryHubState.searchQuery = q || '';
  if (window.treasuryHubState.activeTab === 'book_new') {
    const input = document.getElementById('book-work-search-input');
    if (input) input.value = q || '';
    filterBookWorkDropdown(q || '');
  } else {
    const container = document.getElementById('main-content');
    if (container) renderTreasuryBillHub(container);
  }
}

function clearTreasuryBill(workCode, category, customAmount) {
  if (!state.db || !category) return;
  const list = state.db[category] || [];
  const w = list.find(item => (item.workCode === workCode) || (item.code === workCode));
  if (!w) {
    showToast('Work record not found in database!', 'error');
    return;
  }

  const bookedAmt = Number(w.expdtBookedTreasury) || 0;
  const clearAmt = customAmount !== undefined ? Number(customAmount) : bookedAmt;
  if (clearAmt <= 0) {
    showToast('Invalid clearance amount!', 'error');
    return;
  }

  // 1. Shift amount from Treasury Booked to Actual Expenditure
  w.expdtBookedTreasury = Math.max(0, bookedAmt - clearAmt);
  w.actualExpdtAllotment = (Number(w.actualExpdtAllotment) || 0) + clearAmt;
  w.actualExpdtTotal = (Number(w.actualExpdtAllotment) || 0) + (Number(w.actualExpdtContingency) || 0);

  // 2. Recalculate Cumulative Expenditure
  const cumml0326 = Number(w.cummlExpdtEnding0326) || 0;
  w.cummlExpdt = cumml0326 + w.actualExpdtTotal;

  // 3. Recalculate Savings
  const allot = Number(w.allotmentCost) || 0;
  w.savings = Math.max(0, allot - w.actualExpdtTotal);

  // 4. Save to local storage and memory
  saveData();

  // 5. Push live to Google Sheet via Webhook
  pushWorkToGoogleSheet('update', w, category);

  // 6. Refresh view and show toast
  refreshCurrentView();
  showToast(`Bill of ₹${clearAmt.toFixed(3)} L for "${(w.name || '').substring(0, 30)}..." successfully CLEARED into Expenditure! Google Sheet synced live.`, 'success');
}

function rejectTreasuryBill(workCode, category) {
  if (!state.db || !category) return;
  const list = state.db[category] || [];
  const w = list.find(item => (item.workCode === workCode) || (item.code === workCode));
  if (!w) return;

  const bookedAmt = Number(w.expdtBookedTreasury) || 0;
  if (confirm(`Are you sure you want to REJECT / RETURN this bill of ₹${bookedAmt.toFixed(3)} L for "${(w.name || '').substring(0, 35)}..."? The booked amount will be cleared without adding to expenditure.`)) {
    w.expdtBookedTreasury = 0;
    saveData();
    pushWorkToGoogleSheet('update', w, category);
    refreshCurrentView();
    showToast(`Bill of ₹${bookedAmt.toFixed(3)} L rejected/returned by Treasury. Booked amount cleared without adding to expenditure. Google Sheet synced.`, 'warning');
  }
}

function bookTreasuryBill(workCode, category, amount) {
  const amt = parseFloat(amount);
  if (isNaN(amt) || amt <= 0) {
    showToast('Please enter a valid bill amount in Lakhs (e.g. 1.45)!', 'error');
    return;
  }
  if (!state.db || !category) return;
  const list = state.db[category] || [];
  const w = list.find(item => (item.workCode === workCode) || (item.code === workCode));
  if (!w) {
    showToast('Please select a valid work from the dropdown!', 'error');
    return;
  }

  w.expdtBookedTreasury = (Number(w.expdtBookedTreasury) || 0) + amt;
  if (category && category.startsWith('mla')) {
    w.expdtTreasury = (Number(w.expdtTreasury) || 0) + amt;
  }
  saveData();
  pushWorkToGoogleSheet('update', w, category);
  
  window.treasuryHubState.activeTab = 'pending';
  refreshCurrentView();
  showToast(`New Bill of ₹${amt.toFixed(3)} L successfully BOOKED in Treasury for "${(w.name || '').substring(0, 30)}..."! Google Sheet updated live.`, 'success');
}

function revertClearedBillToBooked(workCode, category, amount) {
  if (!state.db || !category) return;
  const list = state.db[category] || [];
  const w = list.find(item => (item.workCode === workCode) || (item.code === workCode));
  if (!w) return;

  const revertAmt = amount !== undefined ? Number(amount) : (Number(w.actualExpdtTotal) || 0);
  if (revertAmt <= 0) return;

  if (confirm(`Revert ₹${revertAmt.toFixed(3)} L from Expenditure back to Booked in Treasury for "${(w.name || '').substring(0, 35)}..."?`)) {
    w.actualExpdtAllotment = Math.max(0, (Number(w.actualExpdtAllotment) || 0) - revertAmt);
    w.actualExpdtTotal = (Number(w.actualExpdtAllotment) || 0) + (Number(w.actualExpdtContingency) || 0);
    const cumml0326 = Number(w.cummlExpdtEnding0326) || 0;
    w.cummlExpdt = cumml0326 + w.actualExpdtTotal;
    w.expdtBookedTreasury = (Number(w.expdtBookedTreasury) || 0) + revertAmt;

    saveData();
    pushWorkToGoogleSheet('update', w, category);
    refreshCurrentView();
    showToast(`Expenditure of ₹${revertAmt.toFixed(3)} L reverted back to Booked in Treasury. Google Sheet synced.`, 'info');
  }
}

